async function loadLang() {
  try {
    if (!hasStore) return mem[LANGKEY] === "en" ? "en" : "hu";
    const r = await window.storage.get(LANGKEY, false);
    return r && r.value === "en" ? "en" : "hu";
  } catch (e) { return "hu"; }
}
