function socialInteractionInterest(
  w,
  actorId,
  targetId
) {
  if (
    !actorId ||
    !targetId ||
    actorId === targetId
  ) {
    return 0;
  }

  const actor =
    charById(
      w,
      actorId
    );

  const target =
    charById(
      w,
      targetId
    );

  if (
    !actor ||
    !target
  ) {
    return 0;
  }

  const rel =
    getRel(
      w,
      actorId,
      targetId
    );

  const score =
    Number(
      rel.score
    ) || 0;

  let interest =
    Math.min(
      34,
      Math.abs(score) *
        0.34
    );

  const bond =
    String(
      rel.bond ||
      rel.type ||
      ""
    ).toLowerCase();

  if (
    /crush|rival|ellens|enemy|dating|járnak|spouse|házastárs|ex/.test(
      bond
    )
  ) {
    interest += 24;
  }

  if (
    hasEstablishedBond(rel) && (rel.mood || rel.hidden)
  ) {
    interest += 8;
  }

  if (
    ownStorySnippetAbout(
      actor,
      target
    )
  ) {
    interest += 22;
  }

  if (
    factionRivalryActiveBetween(w, actor, target)
  ) {
    /*
     * Franchise/faction rivals pay attention to each other socially too:
     * comments, subtweets, hate-likes and public reactions become more likely.
     */
    interest += 30;
  }

  if (
    characterIsFlirty(actor) &&
    relationshipRomanceActive(w, actorId, targetId, rel)
  ) {
    interest += 12;
  }

  const obsessionLevel =
    relationshipObsessionLevel(
      w,
      actorId,
      targetId
    );

  if (obsessionLevel > 0) {
    interest +=
      obsessionLevel * 30;
  }

  return interest;
}

/*
 * CHARACTER-DRIVEN + RELATIONSHIP-AWARE COMMENT ACTIVITY
 *
 * A kommentelési gyakoriság karakterenként eltér. Az online aktív,
 * beszédes karakterek több kommentet bírnak el; a quiet/private karakterek
 * ritkábban jelennek meg. A kapcsolat és relevancia továbbra is elsődleges.
 */
function fairCommentCast(w, targetId, post = null) {
  const cutoff =
    now() - 48 * 3600e3;

  const target =
    charById(w, targetId);

  const chars = (w.chars || [])
    .filter(
      (c) =>
        c &&
        !isHuman(w, c.id) &&
        c.id !== targetId
    )
    .map((c) => {
      let recentComments = 0;
      let lastCommentAt = 0;

      (w.posts || []).forEach((p) => {
        safePostComments(p).forEach(
          (comment) => {
            if (
              !comment ||
              comment.authorId !== c.id
            ) {
              return;
            }

            const ts =
              Number(comment.ts) || 0;

            if (ts >= cutoff) {
              recentComments += 1;
            }

            lastCommentAt = Math.max(
              lastCommentAt,
              ts
            );
          }
        );
      });

      const rel =
        getRel(w, c.id, targetId);
      const score =
        Number(rel && rel.score) || 0;
      const interest =
        socialInteractionInterest(
          w,
          c.id,
          targetId
        );
      const visualPriority =
        visualPostRelationshipPriority(
          w,
          c.id,
          targetId,
          post
        );
      const following =
        isFollowing(
          w,
          c.id,
          targetId
        );
      const storyLinked =
        Boolean(
          target &&
          ownStorySnippetAbout(c, target)
        );

      /*
       * Feed realism: a follower or someone with a real personal/story reason
       * naturally sees the post. A totally unrelated non-follower can still
       * discover it occasionally, but should not behave like a guaranteed
       * member of every comment section.
       */
      const naturallyLinked =
        following ||
        Math.abs(score) >= 10 ||
        hasEstablishedBond(rel) ||
        storyLinked ||
        interest >= 14 ||
        visualPriority >= 20;

      const activity = characterOnlineActivityProfile(w, c).comment;

      const discoveryChance =
        Math.min(
          0.72,
          (0.18 + interest / 320) * Math.max(0.55, activity)
        );

      const discovered =
        !naturallyLinked &&
        Math.random() < discoveryChance;

      const visibilityBonus =
        (
          following
            ? 34
            : naturallyLinked
              ? 14
              : discovered
                ? 4
                : 0
        ) + visualPriority;

      return {
        c,
        recentComments,
        lastCommentAt,
        interest,
        following,
        eligible:
          naturallyLinked || discovered,
        visibilityBonus,
        activity,
        visualPriority,
        tie: Math.random(),
      };
    });

  chars.sort((a, b) => {
    /*
     * Relevance + believable feed visibility + PERSONAL activity rhythm.
     * A highly-online character may comment repeatedly; a private character
     * pays a larger recent-activity penalty and therefore appears less often.
     */
    const ap =
      a.recentComments * (20 / Math.max(0.35, a.activity)) -
      a.interest -
      a.visibilityBonus -
      (a.activity - 1) * 24;

    const bp =
      b.recentComments * (20 / Math.max(0.35, b.activity)) -
      b.interest -
      b.visibilityBonus -
      (b.activity - 1) * 24;

    if (ap !== bp) {
      return ap - bp;
    }

    if (
      a.lastCommentAt !==
      b.lastCommentAt
    ) {
      return (
        a.lastCommentAt -
        b.lastCommentAt
      );
    }

    return a.tie - b.tie;
  });

  const eligible =
    chars.filter((x) => x.eligible);

  /*
   * Keep enough candidates for an active world, but do not pretend every
   * unrelated NPC saw every post. The AI still decides comment / like / ignore.
   */
  const pool =
    eligible.length >= 5
      ? eligible
      : chars.slice(
          0,
          Math.min(8, chars.length)
        );

  const visual = visualPostReactionProfile(w, post);
  const castLimit = visual.hasImage
    ? (visual.appearanceForward ? 22 : 20)
    : 19;

  /*
   * Prefer NEW voices on a post before recycling somebody who has already left
   * a top-level comment there. They can still re-enter naturally through the
   * separate reply/thread system.
   */
  const alreadyTopLevel = new Set(
    safePostComments(post)
      .filter((comment) => comment && !comment.parent && comment.authorId)
      .map((comment) => comment.authorId)
  );

  const freshVoices = pool.filter((row) => !alreadyTopLevel.has(row.c.id));
  const orderedPool = freshVoices.length >= Math.min(4, pool.length)
    ? freshVoices.concat(pool.filter((row) => alreadyTopLevel.has(row.c.id)))
    : pool;

  return orderedPool
    .map((x) => x.c)
    .slice(0, castLimit);
}

/* CLAUDE FIX R3: the comment being answered (and what it replies to) is repeated
   in the protected tail, so a long prompt can never lose it. */
/* CLAUDE FIX R14 (7.1–7.3): Sims-like social dynamics inside comment threads. */
let REPLY_DYNAMIC_CONTEXT = null;
