/* MÁSVILÁG PLAYER POST COMMENT CONTENT ISOLATION v1 */
const PLAYER_POST_COMMENT_TECH_LEAK_RE =
  /\b(?:variables?|json|prompt|backlog|queue|cache|tokens?|system(?:\s+(?:message|prompt))?|schema|payload|debug|api|function|javascript|typescript|field\s*name|internal\s+instruction|model\s+instruction)\b|(?:változó(?:k|kat|val)?|belső\s+utasítás|rendszerprompt|hibakeresési\s+szöveg)/iu;

const PLAYER_POST_COMMENT_FOLLOW_RE =
  /\b(?:follow(?:ing|ed)?|follow\s*back|unfollow(?:ed|ing)?|click(?:ing|ed)?\s+(?:the\s+)?follow|fan\s*club|add(?:ing|ed)?\s+(?:the\s+)?whole\s+(?:town|world|everyone)|bekövet(?:és|ett|ni)?|visszakövet(?:és|ett|ni)?|kikövet(?:és|ett|ni)?|követget(?:sz|ed|és)?)\b/iu;

const PLAYER_POST_COMMENT_POSITIVE_RE =
  /\b(?:love|adore|cute|pretty|beautiful|gorgeous|hot|amazing|iconic|proud|sweet|funny|perfect|slay|queen|king|support|szeret|imád|cuki|szép|gyönyörű|dögös|büszke|vicces|tökéletes|zseniális)\b|[❤️❤🥰😍💖💕😂🤣]/iu;

const PLAYER_POST_COMMENT_NEGATIVE_RE =
  /\b(?:hate|pathetic|stupid|idiot|annoying|embarrassing|cringe|loser|waste|shut\s*up|boring|desperate|utál|szánalmas|hülye|idióta|idegesítő|kínos|unalmas|rosszindulatú)\b/iu;

const PLAYER_POST_COMMENT_JEALOUS_RE =
  /\b(?:jealous|jealousy|possessive|mine|my\s+(?:girl|boy|girlfriend|boyfriend|woman|man)|steal(?:ing|s)?\s+(?:my|your)\s+(?:girl|boy|girlfriend|boyfriend|woman|man)|who(?:'s| is)\s+that|féltékeny|féltékenység|enyém|az\s+én\s+(?:csajom|pasim)|ki\s+ez)\b/iu;

function playerPostCommentOfficialCouple(w, actorId, targetId) {
  if (!w || !actorId || !targetId || actorId === targetId) return false;
  try {
    const status = String(explicitMutualStatus(w, actorId, targetId) || "");
    return ["seeing", "dating", "engaged", "spouse", "fake-dating"].includes(status);
  } catch (error) {
    return false;
  }
}

function playerPostCommentPossessiveClaimAllowed(w, actorId, text, postContext, card = null) {
  const value = String(text || "").replace(/[’‘]/g, "'");
  if (!POSSESSIVE_CLAIM_RE.test(value)) return true;

  const relevant = new Set();
  if (postContext && postContext.authorId) relevant.add(String(postContext.authorId));
  ((postContext && postContext.taggedPeople) || []).forEach((row) => {
    if (row && row.id) relevant.add(String(row.id));
  });
  ((card && card.relationshipToPeopleNamedInPost) || []).forEach((row) => {
    if (row && row.id) relevant.add(String(row.id));
  });

  return [...relevant].some((targetId) =>
    targetId &&
    targetId !== actorId &&
    playerPostCommentOfficialCouple(w, actorId, targetId)
  );
}

function commentReplyPossessiveClaimAllowed(w, actorId, text, post, comment) {
  const value = String(text || "").replace(/[’‘]/g, "'");
  if (!POSSESSIVE_CLAIM_RE.test(value)) return true;

  const relevant = new Set([
    post && post.authorId,
    comment && comment.authorId,
  ].filter(Boolean).map(String));

  try {
    namedPeopleInText(
      w,
      String(post && post.text || "") + " " + String(comment && comment.text || ""),
      actorId
    ).forEach((id) => { if (id) relevant.add(String(id)); });
  } catch (error) { /* keep only explicit author/addressee */ }

  return [...relevant].some((targetId) =>
    targetId &&
    targetId !== actorId &&
    playerPostCommentOfficialCouple(w, actorId, targetId)
  );
}

function playerPostCommentPostContext(w, post) {
  const tagged = new Set();

  (Array.isArray(post && post.taggedIds) ? post.taggedIds : []).forEach((id) => {
    if (id && charById(w, id)) tagged.add(String(id));
  });
  (Array.isArray(post && post.mentions) ? post.mentions : []).forEach((value) => {
    const raw = typeof value === "object" ? (value.id || value.characterId || value.username || "") : value;
    const id = raw ? findChar(w, raw) : "";
    if (id) tagged.add(String(id));
  });

  const visibleText = String(post && (post.text || post.caption) || "");
  namedPeopleInText(w, visibleText, post && post.authorId).forEach((id) => tagged.add(String(id)));
  const handles = visibleText.match(/@[A-Za-z0-9_.-]+/g) || [];
  handles.forEach((handle) => {
    const clean = handle.slice(1).toLowerCase();
    const c = (w.chars || []).find((row) =>
      row &&
      [row.username, row.handle].filter(Boolean).some((name) =>
        String(name).replace(/^@/, "").toLowerCase() === clean
      )
    );
    if (c) tagged.add(c.id);
  });

  const imageDescription = String(
    post && (
      post.imageDescription ||
      post.imagePrompt ||
      post.imageAlt ||
      post.alt ||
      post.imageCaption ||
      ""
    ) || ""
  ).trim();

  const isQuestion = /\?|\b(?:who|what|when|where|why|how|anyone|valaki|ki|mi|mikor|hol|miért|hogyan)\b/iu.test(visibleText);
  const isInvitation = /\b(?:anyone\s+up\s+for|who\s+wants\s+to|join\s+me|come\s+with|party|hang\s*out|meet\s+up|coffee|drinks?|dinner|valaki\s+jön|ki\s+jön|gyertek|gyere|buli|találkozz|kávé|ital|vacsora)\b/iu.test(visibleText);
  const hasImage = Boolean(post && (post.imageId || post.image));

  return {
    postId: String(post && post.id || ""),
    authorId: String(post && post.authorId || ""),
    authorName: nameOfIn(w, post && post.authorId),
    text: visibleText,
    isQuestion,
    isInvitation,
    hasImage,
    imageDescription,
    imageDescriptionStatus: hasImage ? (imageDescription ? "available" : "missing-do-not-infer") : "no-image",
    mood: String(post && (post.mood || post.feeling || post.vibe) || ""),
    visibleTags: Array.isArray(post && post.tags) ? post.tags.map(String).slice(0, 16) : [],
    taggedPeople: [...tagged].map((id) => ({
      id,
      name: nameOfIn(w, id),
    })),
  };
}

function playerPostCommentExpectedTone(rel) {
  const score = Number(rel && rel.score) || 0;
  const text = [
    rel && rel.bond,
    rel && rel.type,
    rel && rel.mood,
  ].filter(Boolean).join(" ").toLowerCase();

  if (/jealous|féltéken|possess|birtokl/.test(text)) return "jealous";
  if (/enemy|ellens|rival|rivális|hate|utál/.test(text) || score <= -20) return "negative";
  if (/crush|dating|partner|couple|pár|love|szeret|best friend|legjobb barát|close friend|közeli barát|friend|barát/.test(text) || score >= 15) return "positive";
  return "neutral";
}

/* MÁSVILÁG ENEMY + SHEET RESTART GUARDS v1 */
const PLAYER_POST_COMMENT_ENEMY_SUPPORT_RE =
  /\b(?:you\s+got\s+this|you(?:'ve| have)\s+got\s+this|keep\s+(?:going|grinding|pushing|it\s+up)|stay\s+(?:focused|strong)|good\s+luck|rooting\s+for\s+you|believe\s+in\s+you|proud\s+of\s+you|don['’]?t\s+let\s+.*\s+get\s+to\s+you|show\s+them|go\s+get\s+it|nice\s+work|great\s+work|well\s+done|congrats?|respect|hajrá|csak\s+így\s+tovább|ügyes\s+vagy|büszke\s+vagyok\s+rád|szurkolok\s+neked|menni\s+fog|ne\s+hagyd,?\s+hogy.*letörjön)\b|[🔥💪👏🙌]/iu;

function playerPostCommentIsEnemyCard(card) {
  const rel = card && card.relationshipToPostAuthor || {};
  const labels = [rel.type, rel.officialStatus].filter(Boolean).join(" ").toLowerCase();
  return /enemy|ellens/.test(labels) || Number(rel.score) <= -70;
}

function playerPostCommentGeneratedTone(text) {
  const value = String(text || "");
  if (PLAYER_POST_COMMENT_JEALOUS_RE.test(value)) return "jealous";
  if (PLAYER_POST_COMMENT_NEGATIVE_RE.test(value)) return "negative";
  if (PLAYER_POST_COMMENT_POSITIVE_RE.test(value)) return "positive";
  return "neutral";
}

function playerPostCommentVoiceCard(w, c) {
  if (!c) return "";
  try {
    if (typeof voiceStyleCardsForIds === "function") {
      return String(voiceStyleCardsForIds(w, [c.id], c.id) || "").slice(0, 3600);
    }
  } catch {}
  return String(c.aiVoiceStyleCard && c.aiVoiceStyleCard.card || "").slice(0, 2600);
}

function playerPostCommentCandidateCards(w, post, maxComments) {
  const named = namedPeopleInText(w, String(post && (post.text || post.caption) || ""), post && post.authorId)
    .map((id) => charById(w, id)).filter((c) => c && !isHuman(w, c.id)).slice(0, 3);
  const cast = [...named, ...fairCommentCast(w, post.authorId, post).filter((c) => c && !named.some((x) => x.id === c.id))]
    .filter((c) => c && c.id && !isHuman(w, c.id))
    .slice(0, Math.max(2, Math.min(8, Number(maxComments) || 4)));

  return cast.map((c) => {
    const rel = getRel(w, c.id, post.authorId) || EMPTY_REL;
    let official = "";
    try {
      if (typeof officialRelationshipStatusForPair === "function") {
        official = String(officialRelationshipStatusForPair(w, c.id, post.authorId, worldLanguage(w, post.authorId)) || "");
      }
    } catch {}

    return {
      id: c.id,
      name: c.name,
      voiceStyleCard: playerPostCommentVoiceCard(w, c),
      relationshipToPostAuthor: {
        score: Math.max(-100, Math.min(100, Number(rel.score) || 0)),
        type: String(rel.bond || rel.type || ""),
        officialStatus: official,
        currentMood: String(rel.mood || ""),
        expectedPublicTone: playerPostCommentExpectedTone(rel),
        romanticInterest: Boolean(relationshipCrushActive(w, c.id, post.authorId, rel)),
        officialCouple: playerPostCommentOfficialCouple(w, c.id, post.authorId),
      },
      isNamedInPost: named.some((x) => x.id === c.id),
      relationshipToPeopleNamedInPost: named.filter((x) => x.id !== c.id).map((x) => {
        const r = getRel(w, c.id, x.id) || EMPTY_REL;
        return {
          id: x.id,
          name: x.name,
          type: String(r.label || r.bond || r.type || ""),
          score: Number(r.score) || 0,
          mood: String(r.mood || ""),
          officialCouple: playerPostCommentOfficialCouple(w, c.id, x.id),
        };
      }),
    };
  });
}

function playerPostCommentHasFollowLeak(postContext, text) {
  const source = [
    postContext && postContext.text,
    postContext && postContext.imageDescription,
    postContext && postContext.mood,
    ...((postContext && postContext.visibleTags) || []),
  ].filter(Boolean).join(" ");
  if (PLAYER_POST_COMMENT_FOLLOW_RE.test(source)) return false;
  return PLAYER_POST_COMMENT_FOLLOW_RE.test(String(text || ""));
}

/* CLAUDE FIX R18: generic sanity checks for a short social text written as
   one character — the most common nonsense the small model produced. */
function generatedSocialTextSanityProblem(w, actorId, text, card) {
  const value = String(text || "");
  const actor = charById(w, actorId);
  if (!actor) return "";
  /* R53b: a comment to the player about a shared past that never happened */
  try { if (w && w.meId && stripInventedSharedPast(w, actorId, value, [w.meId]) !== value) return "invented-shared-past"; } catch (error) { /* ignore */ }
  /* every capitalised part of the own name (handles "Park Nam-gyu" as well as "Brent LaRusso");
     case-sensitive, so "the park" is not mistaken for "Park" */
  const names = [...String(actor.name || "").split(/\s+/), nicknameInfo(actor.nick).name]
    .filter((n) => n && n.length >= 3 && /^\p{Lu}/u.test(n));
  const low = value.toLowerCase();
  for (const n of [...new Set(names)]) {
    const esc = n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const re = new RegExp("(^|[^\\p{L}])" + esc + "(?=$|[^\\p{L}])", "u");
    if (re.test(value) && !new RegExp("(?:i'?m|i am|call me|it'?s|this is|name'?s|vagyok|hívj)\\s+(?:\\p{L}+\\s+)?" + esc.toLowerCase(), "u").test(low)) return "self-named-in-third-person";
  }
  const cardText = JSON.stringify(card || {}).toLowerCase();
  if (/\b(?:last time|remember when|like (?:that|the) time|again\?? like|the other night|last (?:night|week|weekend) you|múltkor|emlékszel(?:, amikor)?|legutóbb)\b/i.test(value)) {
    const words = low.replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter((x) => x.length >= 5);
    if (!words.some((x) => cardText.includes(x))) return "invented-shared-past";
  }
  if (value.length > 260) return "too-long";
  return "";
}

function playerPostCommentRowsFromOutput(w, out, cards, postContext) {
  const allowed = new Set(cards.map((row) => row.id));
  const seen = new Set();
  const rows = [];

  safeAiComments(out).forEach((row) => {
    try {
      if (!row || typeof row !== "object") return;
      const actorId = findChar(
        w,
        row.id !== undefined
          ? row.id
          : (row.authorId !== undefined ? row.authorId : row.name)
      );
      const text = normalizeGeneratedSocialText(row.text);
      const reactsToRaw = String(row.reagal_erre || row.reactsTo || row.trigger || "").trim();
      const reactsTo = reactsToRaw || String(
        postContext.text ||
        postContext.imageDescription ||
        (postContext.visibleTags || []).join(" ") ||
        "current post"
      ).trim();

      if (!actorId || !allowed.has(actorId) || isHuman(w, actorId) || !text || seen.has(actorId)) return;
      if (!reactsToRaw) {
        console.info("[player-post-comments] normalized=missing-reagal_erre", "character=" + actorId);
      }
      if (PLAYER_POST_COMMENT_TECH_LEAK_RE.test(text)) {
        console.warn("[player-post-comments] rejected=technical-leak", "character=" + actorId, "text=" + text.slice(0, 180));
        return;
      }
      if (playerPostCommentHasFollowLeak(postContext, text)) {
        console.warn("[player-post-comments] rejected=follow-context-leak", "character=" + actorId, "text=" + text.slice(0, 180));
        return;
      }
      const actorCard = cards.find((card) => card && card.id === actorId);
      if (!playerPostCommentPossessiveClaimAllowed(w, actorId, text, postContext, actorCard)) {
        console.warn("[player-post-comments] rejected=unfounded-possessive-claim", "character=" + actorId, "text=" + text.slice(0, 180));
        return;
      }
      const sanity = generatedSocialTextSanityProblem(w, actorId, text, actorCard);
      if (sanity) {
        console.warn("[player-post-comments] rejected=" + sanity, "character=" + actorId, "text=" + text.slice(0, 180));
        return;
      }

      const postWords = new Set(String([postContext.text, postContext.imageDescription, ...(postContext.visibleTags || [])].filter(Boolean).join(" ")).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter((x) => x.length >= 3));
      const groundingWords = String(reactsTo + " " + text).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter((x) => x.length >= 3);
      /* R46: a 1–3 word post ("oh fuck me", "ugh", "finally") shares no words with a
         natural reaction ("what happened??") — judge those by reagal_erre only */
      const grounded = !postWords.size || postWords.size <= 3 || groundingWords.some((x) => postWords.has(x)) || (postContext.isInvitation && /\b(?:yes|yeah|yep|sure|i'?m\s+in|count\s+me\s+in|coming|ott\s+leszek|megyek|benne\s+vagyok|persze|igen)\b/iu.test(text));
      if (!grounded) {
        console.warn("[player-post-comments] rejected=off-topic", "character=" + actorId, "reagal_erre=" + reactsTo.slice(0, 120));
        return;
      }

      const commenterCard = cards.find((card) => card && card.id === actorId);
      if (
        playerPostCommentIsEnemyCard(commenterCard) &&
        (PLAYER_POST_COMMENT_POSITIVE_RE.test(text) || PLAYER_POST_COMMENT_ENEMY_SUPPORT_RE.test(text))
      ) {
        console.warn("[player-post-comments] rejected=enemy-support-hype", "character=" + actorId, "text=" + text.slice(0, 180));
        return;
      }

      seen.add(actorId);
      rows.push({ ...row, id: actorId, text, reagal_erre: reactsTo });
    } catch (error) {
      console.warn("[player-post-comments] rejected=invalid-row", error);
    }
  });

  return rows;
}

function playerPostCommentBatchProblems(w, rows, cards, postContext, minComments) {
  const problems = [];
  const rawRows = Array.isArray(rows) ? rows : [];

  /* R77: the prompt asks for 5-8; only a batch well short of that is retried (a retry doubles the cost) */
  if (rawRows.length < Math.max(2, (Number(minComments) || 2) - 2)) {
    problems.push("too-few-valid-comments");
  }

  const expectedById = new Map(cards.map((card) => [
    card.id,
    card.relationshipToPostAuthor.expectedPublicTone,
  ]));
  const expectedSet = new Set(
    rawRows.map((row) => expectedById.get(findChar(w, row.id)) || "neutral")
  );
  const generatedSet = new Set(
    rawRows.map((row) => playerPostCommentGeneratedTone(row.text))
  );

  if (rawRows.length >= 3 && expectedSet.size >= 2 && generatedSet.size <= 1) {
    problems.push("uniform-tone-despite-different-relationships");
  }

  const stop = new Set([
    "this","that","with","from","your","youre","just","really","like","have","what","when","then","they","them",
    "hogy","amit","csak","mert","egy","azt","most","vagy","volt","még","mar","már","nem","igen","neked","veled"
  ]);
  const tokenSets = rawRows.map((row) => new Set(
    String(row.text || "")
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, " ")
      .split(/\s+/)
      .filter((token) => token.length >= 4 && !stop.has(token))
  ));
  let pairs = 0;
  let similar = 0;
  for (let i = 0; i < tokenSets.length; i += 1) {
    for (let j = i + 1; j < tokenSets.length; j += 1) {
      const a = tokenSets[i];
      const b = tokenSets[j];
      const union = new Set([...a, ...b]);
      if (!union.size) continue;
      pairs += 1;
      const common = [...a].filter((token) => b.has(token)).length;
      if (common / union.size >= 0.48) similar += 1;
    }
  }
  if (pairs >= 3 && similar / pairs >= 0.72) {
    problems.push("comments-repeat-the-same-topic-or-wording");
  }

  rawRows.forEach((row) => {
    if (PLAYER_POST_COMMENT_TECH_LEAK_RE.test(String(row.text || ""))) {
      problems.push("technical-language-leak");
    }
    if (playerPostCommentHasFollowLeak(postContext, row.text)) {
      problems.push("follow-event-leak");
    }
    const actorId = findChar(w, row && (row.id !== undefined ? row.id : (row.authorId !== undefined ? row.authorId : row.name)));
    const actorCard = cards.find((card) => card && card.id === actorId);
    if (actorId && !playerPostCommentPossessiveClaimAllowed(w, actorId, row.text, postContext, actorCard)) {
      problems.push("unfounded-possessive-claim:" + actorId);
    }
  });

  return [...new Set(problems)];
}

function playerPostCommentPrivateSystem(w, post) {
  const en = worldLanguage(w, post.authorId) === "en";
  return en
    ? [
        "You generate authentic social-media comments for exactly ONE visible player post.",
        "The CHARACTER CONTENT block in the user message is the entire visible subject of the comments.",
        "Do not use recent follows, unfollows, queues, backlogs, unrelated timeline events, or any fact not present in that block.",
        "COMMENTER CARDS are private behavioral instructions only. Never quote, expose, explain, or mention their fields.",
        "WHO IS WHO and WORLD GROUPS are background knowledge for understanding the post's references and hints (who is a sensei, who belongs where); they are not topics to comment about on their own.",
        "Each commenter must react to the actual post text/image/mood/tagged people and must sound like their own voice card and relationship to the post author.",
        "Possessive relationship claims such as \"my girl\", \"my boyfriend\", \"mine\" or \"stealing my girl\" are allowed ONLY when the COMMENTER CARD says officialCouple=true for the specific person being claimed. A crush, obsession, jealousy, best friendship or high score is NOT enough.",
        "Positive/friendly relationships should read warm, supportive, playful or naturally flirty when appropriate; ENEMY relationships are hard-adversarial: enemies must NEVER praise, encourage, motivate, congratulate, protect, compliment, admire or hype each other. Enemy comments should be hostile, cold, mocking, dismissive, confrontational, competitive or silent according to character; jealous relationships may be pointed; neutral relationships may be brief and neutral.",
        "Do not make all commenters share one attitude. Do not copy a theme from one commenter into all the others.",
        "Never output software/internal/model terminology such as variable, JSON, prompt, backlog, queue, cache, token, system, schema, payload, debug, API or function.",
        "Return only the requested structured object."
      ].join("\n")
    : [
        "Pontosan EGY látható játékos-poszthoz generálsz hiteles közösségimédia-kommenteket.",
        "A felhasználói üzenet CHARACTER CONTENT blokkja a kommentek TELJES látható témája.",
        "Ne használj korábbi follow/unfollow eseményt, queue/backlog tartalmat, más timeline-eseményt vagy bármi olyat, ami nincs ebben a blokkban.",
        "A COMMENTER CARDS privát viselkedési utasítás. A mezőit soha ne idézd, magyarázd vagy szivárogtasd ki.",
        "A KI KICSODA és a VILÁG CSOPORTJAI háttértudás a poszt utalásainak megértéséhez (ki sensei, ki hová tartozik); önmagukban nem kommenttémák.",
        "Minden kommentelő a konkrét poszt szövegére/képére/hangulatára/tagelt személyeire reagáljon, a saját voice cardja és a poszt szerzőjéhez fűződő kapcsolata szerint.",
        "Birtokló párkapcsolati állítás — pl. \"my girl\", \"a csajom\", \"mine\", \"stealing my girl\" — CSAK annál a konkrét személynél megengedett, akinél a COMMENTER CARD officialCouple=true. Crush, obsession, féltékenység, best friendship vagy magas score önmagában NEM jogosít ilyen állításra.",
        "Pozitív/baráti kapcsolatnál legyen meleg, támogató, játékos vagy indokoltan flörtös; ELLENSÉG kapcsolatnál kemény szabály, hogy SOHA ne dicsérje, biztassa, motiválja, gratuláljon, védje, bókolja, csodálja vagy hype-olja az ellenségét. Az ellenséges komment legyen a karakterhez illően ellenséges, hideg, gúnyos, lekezelő, konfrontatív, versengő vagy maradjon csendben; féltékenynél célzós; semlegesnél rövid és semleges.",
        "Ne legyen minden kommentelő ugyanolyan hangulatú. Egy komment témáját ne másold rá az összes többire.",
        "Soha ne írj ki programozási/belső modellkifejezést: variable, JSON, prompt, backlog, queue, cache, token, system, schema, payload, debug, API, function, változó, belső utasítás.",
        "Csak a kért strukturált objektumot add vissza."
      ].join("\n");
}

function playerPostCommentPrompt(w, post, postContext, cards, minComments, maxComments, retryProblems = [], rejectedRows = []) {
  const en = worldLanguage(w, post.authorId) === "en";
  const retryBlock = retryProblems.length
    ? [
        "",
        "[ONE ALLOWED REGENERATION]",
        "The previous batch was rejected for: " + retryProblems.join(", ") + ".",
        "Do not repeat these rejected comments:",
        JSON.stringify(rejectedRows.map((row) => ({ id: row.id, text: row.text })).slice(0, 6)),
      ].join("\n")
    : "";

  /* CLAUDE FIX R13: who is who + world groups, so jokes about "a sensei" or a
     group land on the right people. */
  let canonCard = "";
  try {
    const namedIds = namedPeopleInText(w, String(post && (post.text || post.caption) || ""), post && post.authorId);
    canonCard = [
      worldGroupGlossaryCard(w),
      whoIsWhoCard(w, [...(cards || []).map((card) => card && card.id).filter(Boolean), ...namedIds]),
      namedPeopleCard(w, namedIds, en) + (namedIds.length ? (en
        ? "\nThe post is about / addressed to these people. Every commenter reacts to them by their OWN relationship to them (relationshipToPeopleNamedInPost); a commenter marked isNamedInPost answers as the one being talked about."
        : "\nA poszt ezekről / ezekhez az emberekről szól. Minden kommentelő a SAJÁT kapcsolata szerint reagál rájuk (relationshipToPeopleNamedInPost); akinél isNamedInPost igaz, az úgy válaszol, mint akiről szó van.") : ""),
    ].filter(Boolean).join("\n\n");
  } catch (error) { canonCard = ""; }
  return [
    canonCard,
    en ? "[CHARACTER CONTENT — VISIBLE POST ONLY]" : "[CHARACTER CONTENT — CSAK A LÁTHATÓ POSZT]",
    JSON.stringify(postContext),
    "",
    en ? "[COMMENTER CARDS — PRIVATE, NEVER OUTPUT THEIR FIELDS]" : "[COMMENTER CARDS — PRIVÁT, A MEZŐKET SOHA NE ÍRD KI]",
    JSON.stringify(cards),
    "",
    en ? "[TASK]" : "[FELADAT]",
    en
      ? "STEP 1 — UNDERSTAND THE POST FIRST: work out what it really means — jokes, wordplay, innuendo, memes, twisted famous phrases or song lines (e.g. \"save a horse, ride a cowboy\" turned into something else), winks like ;) — and who or what it hints at (use WHO IS WHO: who is a sensei, who belongs to which group). Write that in \"postMeaning\" (one sentence)."
      : "1. LÉPÉS — ELŐSZÖR ÉRTSD MEG A POSZTOT: mit jelent valójában — poén, szójáték, kétértelműség, mém, kifordított híres mondat vagy dalszöveg, kacsintás ;) — és kire/mire céloz (használd a KI KICSODA listát: ki sensei, ki melyik csoport tagja). Ezt írd a \"postMeaning\" mezőbe (egy mondat).",
    en
      ? "STEP 2 — every comment reacts to THAT meaning, the way this commenter would: the people it hints at react as the target (flattered, smug, awkward, deflecting, amused); people with a crush or obsession on the author get visibly jealous or possessive if the post flirts with someone else; friends play along or tease; rivals mock. Nobody acts as if they did not get an obvious joke unless that is truly their character."
      : "2. LÉPÉS — minden komment ERRE a jelentésre reagál, ahogy az adott kommentelő tenné: akire céloz, célpontként reagál (hízelgő, önelégült, zavart, hárító, szórakozott); akinek crushja vagy megszállottsága van a szerzőre, láthatóan féltékeny vagy birtokló, ha a poszt mással flörtöl; a barátok beszállnak vagy ugratják; a riválisok gúnyolódnak. Senki ne tegyen úgy, mintha nem értené a nyilvánvaló poént, hacsak tényleg nem ilyen a karaktere.",
    en
      ? "HARD RULES FOR EVERY COMMENT: 3–25 words, complete sentences (never cut off). Each commenter speaks only as themself — never names themself in third person, never speaks for or about another commenter as if they were them. Do not invent past events, parties, accidents or shared memories that are not written in that commenter's card. Use only names and nicknames that appear in WHO IS WHO or the cards; never invent a nickname. A comment must make sense to a stranger reading the post."
      : "KEMÉNY SZABÁLYOK MINDEN KOMMENTRE: 3–25 szó, befejezett mondatok (soha nem félbevágva). Mindenki csak önmagaként szól — magáról nem beszél E/3-ban a saját nevével, és nem beszél más kommentelő helyett. Ne találj ki olyan múltbeli eseményt, bulit, balesetet vagy közös emléket, ami nincs a kommentelő kártyáján. Csak a KI KICSODA listában vagy a kártyákon szereplő neveket és beceneveket használd; ne találj ki becenevet. A kommentnek egy kívülálló számára is értelmesnek kell lennie.",
    /* CLAUDE FIX R63: a question post gets ANSWERS */
    en
      ? "QUESTION POSTS — HARD RULE: if the post asks something (\"prettiest girl you know? name names\", \"who's coming?\", \"best movie?\"), work out exactly what is asked and every commenter ANSWERS it as themself, in their own voice and by their relationships: name a real person from WHO IS WHO when names are asked for (a crush names the poster or their crush, a friend hypes a friend, a rival names someone else to sting). Answers must fit the question literally — a guy is not \"the prettiest girl\", nobody answers a different question. A dodge is fine only if it fits the character, and then it is clearly a dodge of THIS question."
      : "KÉRDÉS-POSZT — KEMÉNY SZABÁLY: ha a poszt kérdez valamit („ki a legszebb lány, akit ismersz? nevezz meg”, „ki jön?”, „legjobb film?”), értsd meg pontosan, mit kérdez, és minden kommentelő VÁLASZOLJON rá önmagaként, a saját hangján és kapcsolatai szerint: ha nevet kér, nevezzen meg valakit a KI KICSODA listából (a crush a posztolót vagy a crushát nevezi meg, a barát a barátját hype-olja, a rivális szúrásból mást nevez meg). A válasz szó szerint illjen a kérdésre — egy fiú nem „a legszebb lány”, és senki nem egy másik kérdésre felel. Kitérni csak karakterhűen lehet, és akkor is egyértelműen EZ elől a kérdés elől.",
    en
      ? "SHORT OR VAGUE POSTS (an exclamation like \"oh fuck me\", \"ugh\", \"finally\"): react to the exclamation itself, as each commenter would — ask what happened, worry, tease, joke, mock — by their relationship. Do NOT explain it with something else from the world (who followed or unfollowed whom, old drama, other posts); nobody knows more than the post says."
      : "RÖVID VAGY HOMÁLYOS POSZT (felkiáltás, pl. \"oh fuck me\", \"ugh\", \"végre\"): magára a felkiáltásra reagáljanak, ahogy az adott kommentelő tenné — mi történt?, aggódás, ugratás, poén, gúny — a kapcsolatuk szerint. NE magyarázd valami mással a világból (ki kit követett be vagy ki, régi dráma, más posztok); senki nem tud többet, mint amit a poszt mond.",
    en
      ? ("Write " + minComments + "-" + maxComments + " top-level comments by DIFFERENT listed commenters. Every comment must directly make sense as a reaction to this exact post." + (postContext.hasImage && postContext.imageDescription ? " The IMAGE DESCRIPTION is what everyone sees: react to the actual outfit / body / place in it (a bikini, lingerie, a gym selfie, a beach), each in their own relationship and personality — no generic 'nice pic'." : ""))
      : ("Írj " + minComments + "-" + maxComments + " TOP-LEVEL kommentet KÜLÖNBÖZŐ felsorolt kommentelőktől. Mindegyik komment közvetlenül ennek a konkrét posztnak a reakciójaként legyen értelmes." + (postContext.hasImage && postContext.imageDescription ? " A KÉPLEÍRÁS az, amit mindenki lát: a képen lévő konkrét ruhára / testre / helyre reagáljanak (bikini, fehérnemű, edzőtermi szelfi, strand), mindenki a saját kapcsolata és személyisége szerint — ne általános 'jó kép'." : "")),
    en
      ? "Use the relationship/voice differences; do not force everyone into the same negative, positive or sarcastic attitude."
      : "Használd a kapcsolat- és voice-különbségeket; ne kényszeríts mindenkit ugyanabba a negatív, pozitív vagy szarkasztikus hangnembe.",
    en
      ? '{"postMeaning":"what the post really means and whom it hints at","comments":[{"id":"EXACT_CHARACTER_ID","text":"natural comment","reagal_erre":"short exact post detail this comment responds to","hangnem":"one of: flirty | supportive | teasing | neutral | jealous | dismissive | hostile"}],"changes":[]}'
      : '{"postMeaning":"mit jelent valójában a poszt és kire céloz","comments":[{"id":"PONTOS_KARAKTER_ID","text":"természetes komment","reagal_erre":"rövid konkrét posztrészlet, amire ez a komment reagál","hangnem":"egy ezek közül: flörtölős | támogató | ugrató | semleges | féltékeny | lekezelő | ellenséges"}],"changes":[]}',
    en
      ? 'If the post is a question or an invitation, answer it (yes / no / where? / who else?). "hangnem" = the real tone of that comment toward the post author.'
      : 'Ha a poszt kérdés vagy meghívás, arra válaszoljanak (jövök / nem jövök / hol lesz? / kivel?). A "hangnem" a komment valódi hangneme a poszt szerzője felé.',
    retryBlock,
    "",
    en
      ? ("THE POST YOU ARE REACTING TO: " + JSON.stringify(postContext.text) + (postContext.isQuestion ? " [QUESTION]" : "") + (postContext.isInvitation ? " [INVITATION]" : "") + (postContext.hasImage ? (postContext.imageDescription ? " [IMAGE DESCRIPTION: " + postContext.imageDescription + "]" : " [IMAGE PRESENT, NO DESCRIPTION AVAILABLE — DO NOT INVENT VISUAL DETAILS]") : ""))
      : ("A POSZT, AMIRE REAGÁLSZ: " + JSON.stringify(postContext.text) + (postContext.isQuestion ? " [KÉRDÉS]" : "") + (postContext.isInvitation ? " [MEGHÍVÁS]" : "") + (postContext.hasImage ? (postContext.imageDescription ? " [KÉPLEÍRÁS: " + postContext.imageDescription + "]" : " [VAN KÉP, DE NINCS LEÍRÁS — NE TALÁLJ KI VIZUÁLIS RÉSZLETEKET]") : "")),
  ].filter(Boolean).join("\n");
}

async function isolatedPlayerPostComments(w, post, options = {}) {
  /* R77: more comments under the player's post — 5-8 instead of 3-6 (never more than the people who can comment) */
  const maxComments = Math.max(5, Math.min(8, Math.round(Number(options.maxComments) || 8)));
  const postContext = playerPostCommentPostContext(w, post);
  const cards = playerPostCommentCandidateCards(w, post, maxComments);
  const minComments = Math.max(1, Math.min(cards.length || 1, maxComments, Math.max(3, Math.round(Number(options.minComments) || 5))));

  if (!cards.length) {
    return { out: { comments: [], changes: [] }, label: "isolated-player-post-comments-no-cast" };
  }

  /* Who reacts is decided locally: the candidate cards are already ranked by relationship,
     and the writing call picks each commenter's tone. No separate planning call. */
  const plannedCards = cards;

  const logContext = {
    post: postContext,
    reactionPlan: "local",
    commenters: plannedCards.map((card) => ({
      id: card.id,
      name: card.name,
      relationshipToPostAuthor: card.relationshipToPostAuthor,
      voiceStyleCard: card.voiceStyleCard,
    })),
  };

  let firstRows = [];
  let firstProblems = [];

  for (let attempt = 0; attempt < 2; attempt += 1) {
    console.info(
      "[player-post-comment-context]",
      "attempt=" + String(attempt + 1),
      "post=" + postContext.postId,
      "context=" + JSON.stringify(logContext).slice(0, 14000)
    );

    const prompt = playerPostCommentPrompt(
      w,
      post,
      postContext,
      plannedCards,
      minComments,
      maxComments,
      attempt ? firstProblems : [],
      attempt ? firstRows : []
    );

    let out;
    try {
      out = await askWorldWritingJSON("comments", 
        w,
        playerPostCommentPrivateSystem(w, post),
        prompt,
        {
          maxTokens: 900,
          priority: 65,
          timeoutMs: 60000,
          source: "player-post-comments-isolated",
          foreground: true,
          memory: backgroundMemory(w, plannedCards.map((card) => card.id), postContext.text),
          participants: [...plannedCards.map((card) => card.id), post.authorId],
          commenters: plannedCards.map((card) => card.id),
        }
      );
    } catch (error) {
      console.error(
        "[player-post-comments]",
        "stage=isolated-ai-result",
        "attempt=" + String(attempt + 1),
        "status=failed",
        "post=" + postContext.postId,
        error
      );
      throw error;
    }

    if (out && out.postMeaning) console.info("[player-post-comments] meaning=" + String(out.postMeaning).slice(0, 240));
    const rows = playerPostCommentRowsFromOutput(w, out, plannedCards, postContext).slice(0, maxComments);
    const problems = playerPostCommentBatchProblems(w, rows, plannedCards, postContext, minComments);

    console.info(
      "[player-post-comments]",
      "stage=isolated-ai-result",
      "attempt=" + String(attempt + 1),
      "status=" + (problems.length ? "rejected" : "success"),
      "post=" + postContext.postId,
      "usable=" + String(rows.length),
      "problems=" + (problems.join("|") || "none")
    );

    if (!problems.length) {
      return {
        out: { ...(out || {}), comments: rows, changes: [] },
        label: "isolated-player-post-comments",
      };
    }

    if (attempt === 0) {
      firstRows = rows;
      firstProblems = problems;
      continue;
    }

    return {
      out: { comments: rows, changes: [] },
      label: "isolated-player-post-comments-retry",
    };
  }

  return { out: { comments: [], changes: [] }, label: "isolated-player-post-comments" };
}

async function genComments(w, post, options = {}) {
  if (post && isHuman(w, post.authorId)) {
    return isolatedPlayerPostComments(w, post, { ...options, playerPostContentIsolation: true });
  }
  return legacyPlayerPostContentGenComments(w, post, options);
}


/* MÁSVILÁG GROUNDED EVENTS + INVITES v2 */
let GROUNDED_REL_EVENT_CONTEXT = null;

const GROUNDED_FALSE_BRENT_RE =
  /saw\s+Angela\s+Mallory\s+Silverman\s+act\s+romantically\/flirtatiously\s+with\s+Brent\s+LaRusso\s+in\s+public/i;

function groundedRuntime(w) {
  if (!w || typeof w !== "object") return null;
  if (!w.sim || typeof w.sim !== "object" || Array.isArray(w.sim)) w.sim = {};
  if (!w.sim.groundedEventsV2 || typeof w.sim.groundedEventsV2 !== "object" || Array.isArray(w.sim.groundedEventsV2)) {
    w.sim.groundedEventsV2 = {};
  }
  const s = w.sim.groundedEventsV2;
  if (!s.pendingFollowBack || typeof s.pendingFollowBack !== "object" || Array.isArray(s.pendingFollowBack)) s.pendingFollowBack = {};
  if (!s.dmUnread || typeof s.dmUnread !== "object" || Array.isArray(s.dmUnread)) s.dmUnread = {};
  if (!Array.isArray(w.eventLog)) w.eventLog = [];
  if (!Array.isArray(w.invitations)) w.invitations = [];
  return s;
}

function groundedEventLog(w, kind, status, message, sourceRef = "", meta = {}) {
  if (!w) return null;
  groundedRuntime(w);
  const row = {
    id: "elog_" + uid(),
    ts: now(),
    kind: String(kind || "event"),
    status: String(status || "info"),
    message: String(message || "").replace(/\s+/g, " ").trim().slice(0, 600),
    sourceRef: String(sourceRef || "").slice(0, 180),
    meta: meta && typeof meta === "object" ? { ...meta } : {},
  };
  w.eventLog.unshift(row);
  if (w.eventLog.length > 220) w.eventLog.length = 220;
  console.info(
    "[event-log]",
    "kind=" + row.kind,
    "status=" + row.status,
    "source=" + (row.sourceRef || "-"),
    "message=" + row.message
  );
  return row;
}

function groundedSourceRef(event) {
  if (!event) return "";
  const meta = event.meta && typeof event.meta === "object" ? event.meta : {};
  const type = String(event.type || "event");
  const ref = meta.commentId || meta.postId || meta.sceneId || meta.popupEventId || event.refId || event.id || "";
  return type + ":" + String(ref || "unknown");
}

function groundedFindComment(w, id) {
  if (!w || !id) return null;
  for (const post of w.posts || []) {
    const row = safePostComments(post).find((c) => c && String(c.id) === String(id));
    if (row) return { post, comment: row };
  }
  return null;
}

function groundedEventIsRecordedFact(w, event) {
  if (!w || !event) return false;
  const type = String(event.type || "").toLowerCase();
  const meta = event.meta && typeof event.meta === "object" ? event.meta : {};
  const ref = String(event.refId || event.id || "");

  if (type === "post") {
    const postId = String(meta.postId || ref);
    return Boolean((w.posts || []).find((p) => p && String(p.id) === postId));
  }
  if (type === "comment" || type === "reply") {
    const commentId = String(meta.commentId || ref);
    return Boolean(groundedFindComment(w, commentId));
  }
  if (type === "follow" || type === "unfollow") {
    const actor = String(event.actorId || "");
    const target = String((event.targetIds || [])[0] || "");
    if (!actor || !target || !charById(w, actor) || !charById(w, target)) return false;
    return type === "follow" ? isFollowing(w, actor, target) : !isFollowing(w, actor, target);
  }
  if (type === "popup-choice") {
    const popupId = String(meta.popupEventId || ref.split(":")[0] || "");
    return Boolean((w.popupEvents || []).find((e) => e && String(e.id) === popupId && e.resolvedAt));
  }
  if (/roleplay|scene/.test(type) || meta.sceneId) {
    const sceneId = String(meta.sceneId || ref);
    return Boolean((w.scenes || []).find((s) => s && String(s.id) === sceneId));
  }
  if (type === "dm-message") {
    const actor = String(event.actorId || "");
    const human = String((event.targetIds || []).find((id) => isHuman(w, id)) || "");
    if (!actor || !human) return false;
    const key = chatKey(actor, human);
    const rows = (w.chats && w.chats[key]) || [];
    return rows.some((m) => {
      if (!m) return false;
      if (ref && String(m.id || "") === ref) return true;
      return Math.abs((Number(m.ts) || 0) - (Number(event.ts) || 0)) < 5000 && String(m.text || "") === String(event.text || "");
    });
  }
  return false;
}

function groundedExplicitRomanticSignal(event) {
  if (!event) return false;
  if (event.meta && event.meta.romantic === true) return true;
  const text = String(event.text || "");
  return /\b(flirt|flirting|kiss|kissing|date|dating|romantic|love\s+you|hot|gorgeous|beautiful|crush|sexy|babe|handsome|vonz|flört|csók|megcsókol|randi|randiz|szerelmes|dögös|gyönyörű|szexi)\b|[😘😍🥰❤️❤💕💖😉😏💋]|;-?\)/iu.test(text);
}

function groundedJealousyEligibility(w, charId, humanId) {
  const c = charById(w, charId);
  if (!c || isHuman(w, charId) || !humanId) return { allowed: false, strength: 0 };
  const rel = getRel(w, charId, humanId) || EMPTY_REL;
  const relationshipText = [rel.bond, rel.type, rel.mood, rel.hidden].filter(Boolean).join(" ").toLowerCase();
  const personalityText = [c.personality, c.traits, c.backstory, c.secrets].filter(Boolean).join(" ").toLowerCase();
  const score = Number(rel.score) || 0;
  const romantic = /love|szerel|crush|vonz|attract|dating|partner|boyfriend|girlfriend|pár|spouse|házastárs|obsess|megszáll/.test(relationshipText);
  const explicitlyJealousPersonality = /jealous|féltéken|possess|birtokl|territorial|obsess|megszáll/.test(personalityText);
  const allowed = romantic || (explicitlyJealousPersonality && score >= 20);
  const strength = allowed ? Math.max(1, Math.min(5, (romantic ? 2 : 0) + (explicitlyJealousPersonality ? 1 : 0) + (score >= 70 ? 2 : score >= 40 ? 1 : 0))) : 0;
  return { allowed, strength };
}

function simsSocialPositiveAttentionEvent(event) {
  const type = String(event && event.type || "").toLowerCase();
  if (type === "like" || type === "follow") return true;
  if (type === "comment" || type === "reply" || type === "post") return groundedExplicitRomanticSignal(event);
  return false;
}

function simsSocialScheduleAttentionRivalry(w, event, subjectId) {
  if (!w || !event || !w.meId || String(event.actorId || "") !== String(w.meId)) return;
  if (!subjectId || subjectId === w.meId || !simsSocialPositiveAttentionEvent(event)) return;
  if (!groundedEventIsRecordedFact(w, event)) {
    groundedEventLog(w, "relationship-trigger", "skipped", "Romantic/jealousy reaction blocked because the source event is not recorded in world state.", groundedSourceRef(event));
    return;
  }
  if (String(event.visibility || "public").toLowerCase() !== "public") return;
  const subject = charById(w, subjectId);
  if (!subject || isHuman(w, subjectId)) return;

  const candidates = (w.chars || [])
    .filter((c) => c && c.id !== subjectId && c.id !== w.meId && !isHuman(w, c.id))
    .map((c) => {
      const eligible = groundedJealousyEligibility(w, c.id, w.meId);
      if (!eligible.allowed) return null;
      if (typeof simsSocialCanObserveEvent === "function" && !simsSocialCanObserveEvent(w, c.id, event)) return null;
      return { c, eligible, score: Number((getRel(w, c.id, w.meId) || {}).score) || 0 };
    })
    .filter(Boolean)
    .sort((a, b) => (b.eligible.strength - a.eligible.strength) || (b.score - a.score));

  const chosen = candidates[0];
  if (!chosen) {
    groundedEventLog(w, "relationship-trigger", "no-reaction", "Public romantic attention had no jealousy-eligible observer.", groundedSourceRef(event));
    return;
  }

  const intel = ensureSocialIntelligenceState(w);
  const key = chosen.c.id + ":attention";
  const last = Number(intel.lastAttentionReaction[key]) || 0;
  if (now() - last < SIMS_SOCIAL_REACTION_COOLDOWN_MS) return;
  intel.lastAttentionReaction[key] = now();

  if (typeof simEnqueue === "function" && typeof mkAction === "function") {
    const queued = simEnqueue(w, mkAction(
      "npc-pair-reaction",
      "grounded-attention-rivalry:" + chosen.c.id + ":" + subjectId + ":" + simsSocialEventKey(event),
      { actorId: chosen.c.id, targetId: subjectId, trigger: "grounded-player-attention-rivalry", eventId: String(event.id || event.refId || ""), jealousyStrength: chosen.eligible.strength },
      "event"
    ));
    groundedEventLog(w, "relationship-trigger", queued ? "queued" : "skipped", chosen.c.name + " may react to a verified public romantic signal; strength=" + chosen.eligible.strength + ".", groundedSourceRef(event), { observerId: chosen.c.id, subjectId });
  }
}

async function genNpcPairReaction(w, actor, target, sourceEvent) {
  if (!sourceEvent || !groundedEventIsRecordedFact(w, sourceEvent)) {
    console.warn("[grounded-event] npc-pair reaction blocked: missing/unverified source event");
    return { skip: true };
  }
  const out = await legacyGroundedGenNpcPairReaction(w, actor, target, sourceEvent);
  if (!out || out.skip === true) return out;
  if (!groundedExplicitRomanticSignal(sourceEvent) && /flirt|romantic|kiss|date|szerel|flört|csók|randi/i.test(String(out.summary || "") + " " + String(out.tone || ""))) {
    console.warn("[grounded-event] rejected invented romantic interpretation", groundedSourceRef(sourceEvent));
    return { skip: true };
  }
  return out;
}

function groundedSanitizeNotificationText(text) {
  return String(text || "")
    .replace(/\bhidden\s*[:=][^•|\n]+/gi, "")
    .replace(/\bsecret(?:ly)?\s+(?:in love|crush|attracted|jealous|possessive)[^•|\n]*/gi, "private feeling")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function pushNote(w, ownerId, note) {
  if (!note || typeof note !== "object") return legacyGroundedPushNote(w, ownerId, note);
  let nextNote = { ...note, text: groundedSanitizeNotificationText(note.text) };
  if (GROUNDED_REL_EVENT_CONTEXT && String(nextNote.text || "").match(/kapcsol|relationship|score|pont|bond|viszony/i)) {
    const suffix = worldLanguage(w, ownerId) === "en" ? " • Source: " + GROUNDED_REL_EVENT_CONTEXT : " • Forrás: " + GROUNDED_REL_EVENT_CONTEXT;
    if (!String(nextNote.text || "").includes(GROUNDED_REL_EVENT_CONTEXT)) nextNote.text = String(nextNote.text || "") + suffix;
  }
  return legacyGroundedPushNote(w, ownerId, nextNote);
}

function simsSocialApplyEventConsequences(w, event) {
  const sourceRef = groundedSourceRef(event);
  if (event && String(event.source || "") === "npc-pair-reaction") {
    const sourceId = String(event.meta && event.meta.sourceEventId || "");
    const sourceEvent = (w.socialEvents || []).find((row) => row && (String(row.id || "") === sourceId || String(row.refId || "") === sourceId));
    if (!sourceEvent || !groundedEventIsRecordedFact(w, sourceEvent)) {
      groundedEventLog(w, "relationship-change", "blocked", "AI-derived relationship consequence blocked because its concrete source event is missing.", sourceRef);
      return;
    }
  }
  const before = {};
  Object.entries((w && w.rels) || {}).forEach(([key, rel]) => { before[key] = Number(rel && rel.score) || 0; });
  const previous = GROUNDED_REL_EVENT_CONTEXT;
  GROUNDED_REL_EVENT_CONTEXT = sourceRef;
  try {
    return legacyGroundedApplyEventConsequences(w, event);
  } finally {
    GROUNDED_REL_EVENT_CONTEXT = previous;
    Object.entries((w && w.rels) || {}).forEach(([key, rel]) => {
      const oldScore = Object.prototype.hasOwnProperty.call(before, key) ? before[key] : Number(rel && rel.score) || 0;
      const newScore = Number(rel && rel.score) || 0;
      if (oldScore === newScore) return;
      groundedEventLog(w, "relationship-change", "applied", key + " " + (newScore - oldScore >= 0 ? "+" : "") + (newScore - oldScore) + " (" + oldScore + "→" + newScore + ")", sourceRef, { relationshipKey: key, delta: newScore - oldScore });
    });
  }
}

function groundedRepairKnownFalseBrentIncident(w) {
  if (!w) return;
  const state = groundedRuntime(w);
  if (state.falseBrentRollbackV1) return;
  const haystack = [...(w.socialEvents || []).map((e) => String(e && e.text || "")), ...Object.values(w.notify || {}).flat().map((n) => String(n && n.text || ""))].join("\n");
  if (!GROUNDED_FALSE_BRENT_RE.test(haystack)) return;
  const corrections = [["Harry Osborn", 10, true], ["Eli Moskowitz", 5, false], ["Terrance Silver", 5, false], ["Feng Xiao", 5, false], ["Daniel LaRusso", 5, false]];
  corrections.forEach(([name, amount, restoreRival]) => {
    const c = (w.chars || []).find((row) => row && String(row.name || "").toLowerCase() === String(name).toLowerCase());
    if (!c || !w.meId) return;
    const rel = getRel(w, c.id, w.meId);
    if (!rel) return;
    rel.score = Math.max(-100, Math.min(100, (Number(rel.score) || 0) + Number(amount)));
    if (restoreRival && !rel.fixed && /enemy|ellens/i.test(String(rel.bond || rel.type || ""))) {
      if ("bond" in rel || !("type" in rel)) rel.bond = "Rival";
      else rel.type = "Rival";
    }
    groundedEventLog(w, "repair", "applied", "Restored erroneous fabricated-Brent deduction for " + name + ": +" + amount + (restoreRival ? ", Enemy→Rival when applicable" : "") + ".", "repair:false-brent-romance");
  });
  state.falseBrentRollbackV1 = now();
  Object.values(w.notify || {}).flat().forEach((note) => {
    if (note && GROUNDED_FALSE_BRENT_RE.test(String(note.text || ""))) note.text = groundedSanitizeNotificationText(String(note.text || "") + (worldLanguage(w, w.meId) === "en" ? " • [Invented event — automatically reverted]" : " • [Hibás, kitalált esemény — automatikusan visszaállítva]"));
  });
}


/* MÁSVILÁG EXPLICIT RELATIONSHIP STATUS ACROSS CHAT / COMMENTS / POSTS v1 */
const EXPLICIT_RELATIONSHIP_STATUS_EVENT_TYPES = new Set([
  "dm-message", "group-message", "comment", "reply", "post"
]);

function explicitRelationshipStatusNormalizedText(value) {
  return normalizeAddressText(
    String(value || "")
      .replace(/["“„][^"”“„\n]{0,240}["”“]/g, " ")
      .replace(/[’‘]/g, "'")
      .replace(/\s+/g, " ")
      .trim()
  );
}

function explicitRelationshipStatusIntent(value) {
  const raw = String(value || "").trim();
  const text = explicitRelationshipStatusNormalizedText(raw);
  if (!text) return null;

  if (
    /^(?:why|what|how|when|where|who|did|do|does|are|is|was|were|should|would|could|can|will|miert|mit|hogyan|mikor|hol|ki|vajon|tenyleg)\b/.test(text) &&
    /[?？]/.test(raw)
  ) return null;

  if (
    /\b(?:did you say|you said|he said|she said|they said|someone said|i heard|we heard|apparently|rumou?r|gossip|reportedly|allitolag|azt mondta|azt mondtad|mondta hogy|mondtad hogy|hallottam|ugy hallottam|pletyka|hirlik)\b/.test(text)
  ) return null;

  if (
    /\b(?:i(?:'m| am)\s+breaking\s+up(?:\s+with\b)?|i\s+broke\s+up\s+with\b|i\s+break\s+up\s+with\b|we\s+broke\s+up\b|we(?:'ve| have)\s+broken\s+up\b|and\s+i\s+broke\s+up\b|we(?:'re| are)\s+done(?:\s*[.!]|$)|we(?:'re| are)\s+over(?:\s*[.!]|$)|it(?:'s| is)\s+over\s+(?:between\s+us|for\s+us)\b|our\s+relationship\s+is\s+over\b|i(?:'m| am)\s+done\s+with\s+you\b|we(?:'re| are)\s+no\s+longer\s+(?:dating|a\s+couple|together)\b|we(?:'re| are)\s+not\s+(?:dating|a\s+couple|together)(?:\s+anymore)?\b|szakitok\s+veled\b|szakitottunk\b|szetmentunk\b|vege\s+koztunk\b|vege\s+a\s+kapcsolatunknak\b|mar\s+nem\s+vagyunk\s+egyutt\b|nem\s+jarunk(?:\s+tobbe)?\b|nem\s+vagyunk\s+egy\s+par\b)/.test(text)
  ) return { kind: "exes", action: "breakup" };

  if (
    /\b(?:we(?:'re| are)\s+married\b|we\s+got\s+married\b|and\s+i\s+are\s+married\b|i(?:'m| am)\s+married\s+to\b|hazasok\s+vagyunk\b|osszehazasodtunk\b)/.test(text)
  ) return { kind: "spouse", action: "married" };

  if (
    /\b(?:we(?:'re| are)\s+engaged\b|we\s+got\s+engaged\b|and\s+i\s+are\s+engaged\b|i(?:'m| am)\s+engaged\s+to\b|jegyesek\s+vagyunk\b|eljegyeztuk\s+egymast\b)/.test(text)
  ) return { kind: "engaged", action: "engaged" };

  if (
    /\b(?:we(?:'re| are)\s+fake[- ]dating\b|we(?:'re| are)\s+pretending\s+to\s+date\b|alkapcsolatban\s+vagyunk\b|csak\s+eljatszuk\s+hogy\s+jarunk\b)/.test(text)
  ) return { kind: "fake-dating", action: "fake-dating" };

  if (
    /\b(?:we(?:'re| are)\s+officially\s+dating\b|we(?:'re| are)\s+dating\b|we(?:'re| are)\s+a\s+couple\b|we\s+made\s+it\s+official\b|and\s+i\s+are\s+dating\b|i(?:'m| am)\s+dating\b|you(?:'re| are)\s+my\s+(?:boyfriend|girlfriend)\b|i(?:'m| am)\s+your\s+(?:boyfriend|girlfriend)\b|hivatalosan\s+egyutt\s+vagyunk\b|egy\s+par\s+vagyunk\b|es\s+en\s+egyutt\s+vagyunk\b|osszejottunk\b|jarunk\s+egymassal\b|te\s+vagy\s+a\s+(?:pasim|csajom|parom)\b)/.test(text)
  ) return { kind: "dating", action: "dating" };

  if (
    /\b(?:we(?:'re| are)\s+seeing\s+each\s+other\b|we(?:'re| are)\s+going\s+out\b|i(?:'m| am)\s+seeing\b|randizgatunk\b|randizunk\s+egymassal\b|randizom\b)/.test(text)
  ) return { kind: "seeing", action: "seeing" };

  if (/\b(?:we(?:'re| are)\s+exes\b|exek\s+vagyunk\b)/.test(text)) {
    return { kind: "exes", action: "exes" };
  }

  return null;
}

function explicitRelationshipStatusBond(kind) {
  return ({
    seeing: "Randizgatnak",
    dating: "Járnak",
    engaged: "Jegyesek",
    spouse: "Házastárs",
    exes: "Exek",
    "fake-dating": "Álkapcsolat",
  })[String(kind || "")] || "";
}

function explicitRelationshipStatusCurrentKind(w, a, b) {
  const shared = explicitMutualStatus(w, a, b);
  if (shared) return shared;

  const forward = directedRomanticOfficialKind(getRel(w, a, b) || EMPTY_REL);
  const reverse = directedRomanticOfficialKind(getRel(w, b, a) || EMPTY_REL);
  const mutual = mutualRomanticFloor(forward, reverse);
  if (mutual) return mutual;

  const kinds = new Set(["seeing", "dating", "engaged", "spouse", "fake-dating", "exes"]);
  if (kinds.has(forward)) return forward;
  if (kinds.has(reverse)) return reverse;
  return "";
}

function explicitRelationshipStatusCurrentPartners(w, actorId) {
  const active = new Set(["seeing", "dating", "engaged", "spouse", "fake-dating"]);
  return socialProfiles(w)
    .filter((person) => person && person.id && person.id !== actorId && !isMediaAccount(w, person.id))
    .filter((person) => active.has(explicitRelationshipStatusCurrentKind(w, actorId, person.id)))
    .map((person) => person.id);
}

function explicitRelationshipStatusTextLinksActorToPerson(w, actorId, personId, value) {
  const person = charById(w, personId);
  if (!person) return false;

  const text = explicitRelationshipStatusNormalizedText(value);
  const aliases = characterAddressAliases(person)
    .map((alias) => normalizeAddressText(String(alias || "").replace(/^@/, "")))
    .filter((alias) => alias.length >= 2);

  return aliases.some((alias) => {
    const core = escapeAddressRegex(alias);
    const token = core + "[\\p{L}'’-]{0,12}";

    return [
      new RegExp("\\b" + token + "\\s+(?:and|&)\\s+i\\b", "iu"),
      new RegExp("\\bi\\s+(?:and|&)\\s+" + token + "\\b", "iu"),
      new RegExp("\\b" + token + "\\s+es\\s+en\\b", "iu"),
      new RegExp("\\ben\\s+es\\s+" + token + "\\b", "iu"),
      new RegExp("\\b(?:with|dating|seeing|married\\s+to|engaged\\s+to)\\s+" + token + "\\b", "iu"),
      new RegExp("\\b" + token + "\\s+(?:is|['’]s)\\s+my\\s+(?:boyfriend|girlfriend|husband|wife|fiance|fiancee|ex)\\b", "iu"),
      new RegExp("\\brandizom\\s+" + token + "\\b", "iu"),
      new RegExp("\\b" + token + "[\\p{L}'’-]{0,12}\\s+(?:szakitottunk|szetmentunk|osszejottunk|randizom)\\b", "iu"),
    ].some((re) => re.test(text));
  });
}

function explicitRelationshipStatusDirectPairLanguage(value) {
  return /\b(?:you|we|us|our|ours|between\s+us|our\s+relationship|veled|koztunk|kapcsolatunk|mi|egymassal|parom|pasim|csajom)\b/.test(
    explicitRelationshipStatusNormalizedText(value)
  );
}

function explicitRelationshipStatusEventTarget(w, event) {
  const actorId = String(event.actorId || "");
  const text = String(event.text || "");
  const meta = event.meta && typeof event.meta === "object" ? event.meta : {};
  const type = String(event.type || "").toLowerCase();

  let named = [];
  try {
    named = namedPeopleInText(w, text, actorId)
      .filter((id) => id && id !== actorId && !isMediaAccount(w, id));
  } catch (error) {
    named = [];
  }

  const linkedNamed = named.find((id) =>
    explicitRelationshipStatusTextLinksActorToPerson(w, actorId, id, text)
  );
  if (linkedNamed) return linkedNamed;

  const directCandidate =
    meta.targetId && String(meta.targetId) !== actorId
      ? String(meta.targetId)
      : (
          Array.isArray(event.targetIds) &&
          event.targetIds.length === 1 &&
          String(event.targetIds[0]) !== actorId
            ? String(event.targetIds[0])
            : ""
        );

  if (
    directCandidate &&
    charById(w, directCandidate) &&
    !isMediaAccount(w, directCandidate) &&
    ["dm-message", "group-message", "comment", "reply"].includes(type) &&
    explicitRelationshipStatusDirectPairLanguage(text)
  ) {
    return directCandidate;
  }

  const partners = explicitRelationshipStatusCurrentPartners(w, actorId);
  return partners.length === 1 ? partners[0] : "";
}

function detectExplicitRelationshipStatusChange(w, event = {}) {
  if (!w || !event) return null;

  const type = String(event.type || "").toLowerCase();
  if (!EXPLICIT_RELATIONSHIP_STATUS_EVENT_TYPES.has(type)) return null;

  const actorId = String(event.actorId || "");
  if (!actorId || isMediaAccount(w, actorId)) return null;

  const intent = explicitRelationshipStatusIntent(event.text);
  if (!intent) return null;

  let targetId = explicitRelationshipStatusEventTarget(w, event);
  if (!targetId || targetId === actorId || isMediaAccount(w, targetId) || !charById(w, targetId)) return null;

  let aRel = getRel(w, actorId, targetId) || EMPTY_REL;
  let bRel = getRel(w, targetId, actorId) || EMPTY_REL;
  if (isPermanentFamilyBond(aRel) || isPermanentFamilyBond(bRel)) return null;

  let currentKind = explicitRelationshipStatusCurrentKind(w, actorId, targetId);

  if (
    intent.kind === "exes" &&
    !["seeing", "dating", "engaged", "spouse", "fake-dating", "exes"].includes(currentKind)
  ) {
    const partners = explicitRelationshipStatusCurrentPartners(w, actorId);
    if (partners.length !== 1) return null;

    targetId = partners[0];
    aRel = getRel(w, actorId, targetId) || EMPTY_REL;
    bRel = getRel(w, targetId, actorId) || EMPTY_REL;
    if (isPermanentFamilyBond(aRel) || isPermanentFamilyBond(bRel)) return null;
    currentKind = explicitRelationshipStatusCurrentKind(w, actorId, targetId);
  }

  if (currentKind === intent.kind) return null;

  const rank = { seeing: 1, dating: 2, engaged: 3, spouse: 4 };
  if (
    intent.kind !== "exes" &&
    intent.kind !== "fake-dating" &&
    currentKind !== "exes" &&
    (rank[currentKind] || 0) > (rank[intent.kind] || 0)
  ) {
    return null;
  }

  return {
    actorId,
    targetId,
    kind: intent.kind,
    action: intent.action,
    eventType: type,
    refId: String(event.refId || event.id || ""),
    text: String(event.text || "").slice(0, 500),
    beforeStatus: officialRelationshipStatusForPair(w, actorId, targetId, CURRENT_LANG),
  };
}

function finalizeExplicitRelationshipStatusChange(w, change) {
  if (!w || !change) return;

  const afterStatus = officialRelationshipStatusForPair(
    w,
    change.actorId,
    change.targetId,
    CURRENT_LANG
  );

  try {
    fullSpecRecordMilestone(
      w,
      change.actorId,
      change.targetId,
      change.beforeStatus || "",
      afterStatus,
      change.eventType || "relationship",
      change.text || change.action || "explicit relationship status change"
    );
  } catch (error) {
    console.warn("[relationship-status-explicit] milestone record failed", error);
  }

  [change.actorId, change.targetId]
    .filter((id) => id && !isHuman(w, id) && charById(w, id))
    .forEach((id) => {
      const otherId = id === change.actorId ? change.targetId : change.actorId;
      try {
        rememberAboutTarget(w, id, otherId, {
          kind: "event",
          source: "explicit_relationship_status",
          confidence: 1,
          text:
            "Official relationship status changed to " +
            officialKindLabel(change.kind, worldLanguage(w, id)) +
            ": " +
            cut(change.text || change.action || "", 220),
        });
      } catch (error) {}
    });
}

function applyExplicitRelationshipStatusFromEvent(w, event = {}, options = {}) {
  const change = detectExplicitRelationshipStatusChange(w, event);
  if (!change) return null;

  const bond = explicitRelationshipStatusBond(change.kind);
  if (!bond) return null;

  if (
    !w.relationshipOfficialOverrides ||
    typeof w.relationshipOfficialOverrides !== "object" ||
    Array.isArray(w.relationshipOfficialOverrides)
  ) {
    w.relationshipOfficialOverrides = {};
  }

  const key = relationshipOfficialOverrideKey(change.actorId, change.targetId);
  w.relationshipOfficialOverrides[key] = {
    kind: change.kind,
    source: "explicit-" + String(change.eventType || "conversation"),
    at: now(),
    actorId: change.actorId,
    refId: change.refId || "",
    explicitEvent: true,
  };

  setRel(w, change.actorId, change.targetId, {
    bond,
    type: "",
    fixed: false,
    why: cut(change.text || change.action || "", 160),
  });

  setRel(w, change.targetId, change.actorId, {
    bond,
    type: "",
    fixed: false,
    why: cut(change.text || change.action || "", 160),
  });

  try {
    const sim = ensureSimState(w);
    if (sim) sim.automaticFollowSyncDirty = true;
  } catch (error) {}

  if (options.recordMilestone !== false) {
    finalizeExplicitRelationshipStatusChange(w, change);
  }

  return change;
}

function explicitRelationshipStatusPromptInstruction(
  w,
  actorId,
  text,
  directTargetId = "",
  surface = "conversation"
) {
  const change = detectExplicitRelationshipStatusChange(w, {
    type: surface === "group chat" ? "group-message" : "dm-message",
    actorId,
    targetIds: directTargetId ? [directTargetId] : [],
    text,
    source: surface,
    meta: { targetId: directTargetId || "" },
  });

  if (!change) return "";

  return (
    "\nRELATIONSHIP STATUS CHANGE IN THIS TURN — HARD FACT:\n" +
    "- " +
    nameOfIn(w, change.actorId) +
    " explicitly changes the shared relationship with " +
    nameOfIn(w, change.targetId) +
    " to " +
    officialKindLabel(change.kind, worldLanguage(w, actorId)) +
    ".\n" +
    "- This takes effect NOW. React from the state AFTER that change; do not keep treating the old official status as current.\n"
  );
}


function recordSocialEvent(w, event = {}) {
  groundedRepairKnownFalseBrentIncident(w);

  let explicitRelationshipStatusChange = null;
  try {
    explicitRelationshipStatusChange =
      applyExplicitRelationshipStatusFromEvent(
        w,
        event,
        { recordMilestone: false }
      );
  } catch (error) {
    console.warn(
      "[relationship-status-explicit] pre-record detection failed; social event preserved",
      error
    );
  }

  const result = legacyGroundedRecordSocialEvent(w, event);

  try {
    if (explicitRelationshipStatusChange) {
      finalizeExplicitRelationshipStatusChange(
        w,
        explicitRelationshipStatusChange
      );
    }

    const ref = groundedSourceRef(event);
    groundedEventLog(w, String(event.type || "social-event"), "recorded", String(event.text || event.type || "Social event recorded."), ref, { actorId: event.actorId || "", targetIds: event.targetIds || [] });
    if (String(event.type || "").toLowerCase() === "dm-message") groundedRegisterIncomingDm(w, event);
  } catch (error) {
    console.warn("[grounded-event] post-record hook failed; base event preserved", error);
  }
  return result;
}

/* CLAUDE FIX 2.3 — bounded follow-back retries + trigger context */
const FOLLOW_BACK_DM_MAX_ATTEMPTS = 3;
const FOLLOW_BACK_DM_RETRY_MS = 5 * 60 * 1000;
let AUTONOMOUS_DM_TRIGGER_CONTEXT = null;

function groundedFollowBackAttemptFailed(w, botId, reason) {
  if (!w || !botId) return;
  const state = groundedRuntime(w);
  const row = state.pendingFollowBack && state.pendingFollowBack[botId];
  if (!row) return;
  row.inFlight = 0;
  row.attempts = (Number(row.attempts) || 0) + 1;
  if (reason === "deferred") row.attempts -= 1;
  if (row.attempts >= FOLLOW_BACK_DM_MAX_ATTEMPTS) {
    delete state.pendingFollowBack[botId];
    groundedEventLog(w, "follow-not-returned", "failed", "Gave up after " + FOLLOW_BACK_DM_MAX_ATTEMPTS + " attempts (" + reason + ").", "follow:" + botId + ">" + String(row.humanId || ""));
    return;
  }
  row.dueAt = now() + FOLLOW_BACK_DM_RETRY_MS * Math.max(1, row.attempts);
  groundedEventLog(w, "follow-not-returned", "failed", "Attempt " + row.attempts + "/" + FOLLOW_BACK_DM_MAX_ATTEMPTS + " failed (" + reason + "); next try in " + Math.round((row.dueAt - now()) / 60000) + " min.", "follow:" + botId + ">" + String(row.humanId || ""));
}

function autonomousDmTriggerDirective(w, bot) {
  const ctx = AUTONOMOUS_DM_TRIGGER_CONTEXT;
  if (!ctx || !bot || String(ctx.botId) !== String(bot.id)) return "";
  const player = (w && w.player && w.player.name) || "a játékos";
  if (ctx.trigger === "follow-not-returned") {
    return "\n\n" + PROTECTED_TAIL_MARKER + "\nEZÉRT ÍRSZ MOST — VALÓDI, MEGTÖRTÉNT ESEMÉNY (KÖTELEZŐ, \"skip\": false):\n" +
      "Bekövetted " + player + " profilját, de " + player + " NEM követett vissza. A személyiséged miatt ez zavar. " +
      "Ebben a DM-ben erre reagálj a saját hangodon: szóvá teszed, kérdőre vonod, sértődötten, rámenősen vagy célzósan rákérdezel, miért nem követ vissza. " +
      "Ne találj ki más okot, ne kérj bocsánatot, és ne írj semleges small talkot helyette.";
  }
  if (ctx.trigger === "player-unfollowed") {
    return "\n\n" + PROTECTED_TAIL_MARKER + "\nEZÉRT ÍRSZ MOST — VALÓDI, MEGTÖRTÉNT ESEMÉNY (KÖTELEZŐ, \"skip\": false):\n" +
      player + " az imént KIKÖVETETT téged (unfollow). Ebben a DM-ben erre reagálj a saját személyiséged és a kapcsolatotok szerint: megbántva, dühösen, kérdőre vonva, gúnyosan, sértetten vagy közönyt mímelve — ahogy te tennéd. Ne találj ki más okot.";
  }
  if (/^comment-dm-/.test(String(ctx.trigger || "")) && ctx.causeText) {
    return "\n\n" + PROTECTED_TAIL_MARKER + "\nEZÉRT ÍRSZ MOST — A KOMMENTEKBEN MEGBESZÉLTÉTEK (KÖTELEZŐ, \"skip\": false):\n" + String(ctx.causeText).slice(0, 500) + "\nÍrj neki most DM-et, pontosan onnan folytatva, a saját hangodon.";
  }
  if (ctx.causeText) {
    return "\n\n" + PROTECTED_TAIL_MARKER + "\nEZ A MEGTÖRTÉNT ESEMÉNY INDÍTOTTA A DM-ET (erre reagálj, ne találj ki mást):\n" + String(ctx.causeText).slice(0, 400);
  }
  return "";
}

function groundedFollowBackPersonalityEligible(w, botId, humanId) {
  const c = charById(w, botId);
  const rel = getRel(w, botId, humanId) || EMPTY_REL;
  if (!c) return false;
  const text = [c.personality, c.traits, c.backstory, c.secrets, rel.bond, rel.mood, rel.hidden].filter(Boolean).join(" ").toLowerCase();
  if (/obsess|megszáll|possess|birtokl|jealous|féltéken|cling|ragaszkod|territorial|proud|büszke|sensitive|érzékeny|confront|konfront/.test(text)) return true;
  /* CLAUDE FIX R3: someone who cares about the player (or has a crush) also notices. */
  return (Number(rel.score) || 0) >= 50 || /crush|vonz|attract|szerelm|in love/.test(String(rel.bond || "") + " " + String(rel.hidden || ""));
}

function setFollowState(w, actorId, targetId, following, reason) {
  const before = isFollowing(w, actorId, targetId);
  const result = legacyGroundedSetFollowState(w, actorId, targetId, following, reason);
  const after = isFollowing(w, actorId, targetId);
  if (!before && after && !isHuman(w, actorId) && isHuman(w, targetId)) {
    const source = String(reason || "");
    if (!/bootstrap|startup|normalize|migration/i.test(source) && !isFollowing(w, targetId, actorId)) {
      const state = groundedRuntime(w);
      state.pendingFollowBack[actorId] = { botId: actorId, humanId: targetId, createdAt: now(), dueAt: now() + 3 * 60 * 1000, reason: source || "follow" };
      groundedEventLog(w, "follow-not-returned", "started", nameOfIn(w, actorId) + " followed " + nameOfIn(w, targetId) + "; follow-back reaction armed.", "follow:" + actorId + ">" + targetId);
    }
  }
  if (before && !after && isHuman(w, actorId) && !isHuman(w, targetId) && charById(w, targetId)) {
    /* CLAUDE FIX R3 (7.4): the player unfollowed a character who cares -> they react once. */
    if (groundedFollowBackPersonalityEligible(w, targetId, actorId) || Math.abs(Number((getRel(w, targetId, actorId) || EMPTY_REL).score) || 0) >= 35) {
      const state = groundedRuntime(w);
      state.pendingFollowBack[targetId] = { botId: targetId, humanId: actorId, createdAt: now(), dueAt: now() + 60 * 1000, reason: "player-unfollowed", trigger: "player-unfollowed" };
      groundedEventLog(w, "player-unfollowed", "started", nameOfIn(w, actorId) + " unfollowed " + nameOfIn(w, targetId) + "; reaction armed.", "unfollow:" + actorId + ">" + targetId);
    } else {
      groundedEventLog(w, "player-unfollowed", "skipped", nameOfIn(w, targetId) + " does not care enough to react to the unfollow.", "unfollow:" + actorId + ">" + targetId);
    }
  }
  if (after && isHuman(w, actorId) && !isHuman(w, targetId)) {
    const state = groundedRuntime(w);
    if (state.pendingFollowBack[targetId] && state.pendingFollowBack[targetId].trigger !== "player-unfollowed") {
      delete state.pendingFollowBack[targetId];
      groundedEventLog(w, "follow-not-returned", "cancelled", "Follow-back arrived before the DM trigger.", "follow:" + targetId + ">" + actorId);
    }
  }
  return result;
}

function groundedDueFollowBackAction(w) {
  if (!w) return null;
  const state = groundedRuntime(w);
  Object.values(state.pendingFollowBack || {}).forEach((row) => { if (row && row.inFlight && now() - Number(row.inFlight) > 3 * 60 * 1000) row.inFlight = 0; });
  const rows = Object.values(state.pendingFollowBack || {}).filter((row) => row && Number(row.dueAt || 0) <= now() && !row.inFlight).sort((a, b) => Number(a.dueAt || 0) - Number(b.dueAt || 0));
  for (const row of rows) {
    if (!charById(w, row.botId) || isHuman(w, row.botId)) { delete state.pendingFollowBack[row.botId]; continue; }
    const rowTrigger = String(row.trigger || "follow-not-returned");
    /* CLAUDE FIX R7 (5.5): no follow/unfollow DM while the player is in a scene or
       chatting in 2+ DM threads; the row stays pending, so the reason is not lost. */
    const followPause = typeof eventDrivenAutonomousDmPauseReason === "function" ? String(eventDrivenAutonomousDmPauseReason(w) || "") : "";
    if (followPause === "scene-active" || followPause === "parallel-dms") {
      if (!row.lastDeferredLogAt || now() - Number(row.lastDeferredLogAt) > 60000) {
        row.lastDeferredLogAt = now();
        groundedEventLog(w, rowTrigger, "deferred", "DM to the player deferred (" + followPause + "); it will be sent afterwards.", "follow:" + row.botId + ">" + row.humanId);
      }
      continue;
    }
    if (rowTrigger === "player-unfollowed") {
      if (isFollowing(w, row.humanId, row.botId)) { delete state.pendingFollowBack[row.botId]; continue; }
      groundedEventLog(w, "player-unfollowed", "started", "Unfollow reaction DM queued for " + nameOfIn(w, row.botId) + " (attempt " + ((Number(row.attempts) || 0) + 1) + "/" + FOLLOW_BACK_DM_MAX_ATTEMPTS + ").", "unfollow:" + row.humanId + ">" + row.botId);
      return mkAction("dm", "grounded-player-unfollowed:" + row.botId + ":" + row.createdAt, { botId: row.botId, trigger: "player-unfollowed", groundedFollowBackBotId: row.botId }, "event");
    }
    if (!groundedFollowBackPersonalityEligible(w, row.botId, row.humanId)) {
      groundedEventLog(w, "follow-not-returned", "failed", "No follow-back DM: character personality/relationship does not justify a direct reaction.", "follow:" + row.botId + ">" + row.humanId);
      delete state.pendingFollowBack[row.botId];
      continue;
    }
    const pauseReason = typeof eventDrivenAutonomousDmPauseReason === "function" ? String(eventDrivenAutonomousDmPauseReason(w) || "") : "";
    if (pauseReason && /scene|roleplay|event/i.test(pauseReason)) {
      if (!row.lastDeferredLogAt || now() - Number(row.lastDeferredLogAt) > 60000) {
        row.lastDeferredLogAt = now();
        groundedEventLog(w, "follow-not-returned", "failed", "Due follow-back DM deferred while player is in an active scene/event: " + pauseReason, "follow:" + row.botId + ">" + row.humanId);
      }
      continue;
    }
    if (!isFollowing(w, row.botId, row.humanId) || isFollowing(w, row.humanId, row.botId)) { delete state.pendingFollowBack[row.botId]; continue; }
    groundedEventLog(w, "follow-not-returned", "started", "Unreturned-follow DM queued for " + nameOfIn(w, row.botId) + " (attempt " + ((Number(row.attempts) || 0) + 1) + "/" + FOLLOW_BACK_DM_MAX_ATTEMPTS + ").", "follow:" + row.botId + ">" + row.humanId);
    return mkAction("dm", "grounded-follow-not-returned:" + row.botId + ":" + row.createdAt, { botId: row.botId, trigger: "follow-not-returned", groundedFollowBackBotId: row.botId }, "event");
  }
  return null;
}


/* =====================================================================
   CLAUDE FIX R2 — RELATIONSHIP READING
   Each character's own Connections entries are read ONCE by the AI (cached by
   a hash of the text) into a directed relationship: score, bond, visible mood,
   hidden feeling, and attraction / fear / obsession / trust. The keyword
   mapper stays only as a fallback. When a reading arrives, the live
   relationship is corrected but the points earned in play are kept.
   ===================================================================== */





/* CLAUDE FIX R38: show that relationships are still being read from the sheets */







/* CLAUDE FIX R36: DEEP PAIR READING. A relationship is no longer read from the
   actor's Connections row alone. Every passage of the actor's WHOLE sheet that
   mentions the other person (backstory, secrets, goals, personality...) goes
   in, and so does what the OTHER person's sheet says about the actor (shared
   history, facts), so the AI sees the full story of the two of them. */







/* versioned so a reading-rule change re-reads every sheet once (R36: deep pair reading) */






function relationshipReadingDueAction(w) {
  if (!w || !w.meId || bondAnalysisBusy.has(w.code) || analysisReady(w, allSubjects) || now() < (bondAnalysisRetry.get(w.code) || 0)) return null;
  return mkAction("relationship-reading", "relationship-reading:" + simsSocialStableHash(bondSourceFingerprint(w, allSubjects)), {}, "memory");
}









/* CLAUDE FIX R40: SHARED READING CACHE. A relationship read once from the
   sheets is stored on the server under a key made of the two names and the
   exact sheet passages. A new world with the same sheets, or a restart, gets
   every unchanged relationship back instantly; only changed ones are read. */













/* =====================================================================
   CLAUDE FIX R6 — IDENTITY CANON ("who is who")
   Each person's own sheet is read ONCE by the AI (cached by a hash of the
   sheet) into public, structural facts: dojo/team/organization, role, their
   sensei/leader, teammates, rivals, relationship status and partner. These
   facts are shown to the AI in every scene / DM / feed prompt, they gate
   flirting (a married character does not return advances), and they seed a
   default attitude for pairs whose sheets do not mention each other.
   ===================================================================== */

/* CLAUDE FIX R17: one-time sheet reading is done carefully, with a stronger
   model (server: quality "deep"), the whole sheet and a focused instruction. */
const SHEET_ANALYST_SYSTEM = [
  "You are a meticulous reader of role-play character sheets for a living social-media story world.",
  "Read EVERY line of the material before answering — every section, every relationship entry, every detail of history, personality and speech.",
  "Extract what the sheet states and carefully infer what it clearly implies (relationships, loyalties, history, personality, how the person talks). Base every conclusion on the text; never invent and never fall back on generic stereotypes or the original fandom's canon when the sheet says otherwise.",
  "Keep nuance and contradictions: a person can be cold in public and soft in private, loyal and jealous at once.",
  "Return JSON only.",
].join("\n");




function isFakeDatingText(value) {
  return /[aá]lkapcsolat|[aá]l-kapcsolat|kamu ?(?:kapcsolat|p[aá]r)|fake[- ]?dat|fake (?:relationship|couple|girlfriend|boyfriend)|pretend(?:ing)? to (?:date|be (?:a )?couple|be together)|fake-dating/i.test(String(value || ""));
}



function fakeDatingBehaviorCard(w, actorId, targetId) {
  const rel = getRel(w, actorId, targetId) || EMPTY_REL;
  const reverse = getRel(w, targetId, actorId) || EMPTY_REL;
  /* R87: the reading may put "fake dating" into the label / description / layers instead of the bond word */
  const saysFake = (r) => [r.bond, r.type, r.label, r.role, r.description, ...(Array.isArray(r.layers) ? r.layers : [])].filter(Boolean).some((v) => isFakeDatingText(v));
  if (!saysFake(rel) && !(reverse.whoKnows?.includes(actorId) && saysFake(reverse))) return "";
  const en = worldLanguage(w, w && w.meId) === "en";
  const target = nameOfIn(w, targetId);
  const real = [rel.mood, rel.hidden].filter(Boolean).join("; ");
  /* a player / fuckboy / commitment-shy type admits real feelings much harder */
  const actor = charById(w, actorId) || {};
  const nature = [actor.personality, actor.traits, actor.extra, actor.speech].filter(Boolean).join(" ");
  const guarded = /fuck ?boy|f\*ckboy|playboy|player\b|womani[sz]er|heartbreaker|commitment|emotionally unavailable|never (?:does|catches) feelings|no strings|casual only|guarded|n[őo]cs[aá]b[aá]sz|csajoz[oó]|szoknyavad[aá]sz|nem k[oö]telez|nem szerelmes t[ií]pus/i.test(nature);
  return en
    ? "FAKE DATING WITH " + target + ": the two of you PRETEND to be a couple. In public (posts, comments, events with others) keep up the act — couple behaviour, pet names, defending the 'relationship', reacting as a partner would. Never reveal publicly that it is fake." +
      " In private (DMs, scenes with only the two of you) the real feelings" + (real ? " (" + real + ")" : "") + " only LEAK — a look held too long, jealousy you deny, staying longer than the deal needs, a softer moment you immediately joke away. Liking them or wanting them is fine to show; ADMITTING that you feel more, that it is not fake for you any more, does not happen in an ordinary DM: you deflect ('it's part of the act', 'don't flatter yourself', a joke, a flirt, a change of subject) and get colder if pressed." +
      (guarded ? " You are the player / commitment-shy type: admitting real feelings is the LAST thing you would do — only after many significant moments, under real pressure (jealousy, almost losing them), and even then half-said and taken back." : "")
    : "ÁLKAPCSOLAT " + target + " FELÉ: ti ketten csak ELJÁTSSZÁTOK, hogy egy pár vagytok. Nyilvánosan (posztok, kommentek, közös események) tartsátok fenn a látszatot — páros viselkedés, becenevek, a „kapcsolat” védelme, partnerként reagálás. Nyilvánosan soha ne áruld el, hogy kamu." +
      " Privátban (DM, kettesben zajló jelenet) a valódi érzéseid" + (real ? " (" + real + ")" : "") + " csak KISZIVÁROGNAK — egy túl hosszú pillantás, letagadott féltékenység, tovább maradsz, mint ami a deal része, egy lágyabb pillanat, amit azonnal elviccelsz. Hogy tetszik vagy kívánod, az látszhat; BEVALLANI, hogy többet érzel, hogy neked már nem kamu, egy hétköznapi DM-ben nem fogod: terelsz („ez a szerep része”, „ne képzeld”, poén, flört, témaváltás), és ha erőltetik, hidegebb leszel." +
      (guarded ? " Te a csajozós / elköteleződéstől menekülő típus vagy: az érzéseid bevallása az utolsó, amit megtennél — csak sok jelentős pillanat után, valódi nyomás alatt (féltékenység, majdnem elveszíted), és akkor is félig kimondva, visszavonva." : "");
}





function identityCanonFor(w, id) {
  const profile = w.bondAnalysis?.profiles?.[id]?.profile;
  if (!profile) return null;
  const claims = Object.fromEntries(profile.claims.map(row => [row.field, row.value]));
  const outgoing = Object.values(w.rels || {}).filter(row => row.from === id);
  const names = rows => rows.map(row => nameOfIn(w, row.to));
  return { ...claims, affiliations: profile.groups, group: profile.groups[0]?.name || "", role: profile.groups[0]?.role || "",
    leader: names(outgoing.filter(row => (row.layers || []).some(layer => ["tanítvány–sensei", "tag–vezető"].includes(layer)))).join(", "),
    teammates: names(outgoing.filter(row => (row.layers || []).some(layer => ["csapattárs", "sensei–tanítvány", "vezető–tag"].includes(layer)))),
    rivals: names(outgoing.filter(row => (row.layers || []).includes("rivális"))), hates: [] };
}

function identityNameMatches(text, person) {
  const hay = String(text || "").toLowerCase();
  if (!hay || !person) return false;
  const names = [person.name, nicknameInfo(person.nick).name, person.username]
    .map((x) => String(x || "").trim().toLowerCase())
    .filter(Boolean);
  const first = String(person.name || "").trim().split(/\s+/)[0].toLowerCase();
  if (first && first.length >= 3) names.push(first);
  return names.some((n) => n.length >= 3 && hay.includes(n));
}

/* The actor is married / engaged / in a relationship with someone OTHER than
   the target, and the sheet does not say they cheat. */
function identityCommittedElsewhere(w, actor, target) {
  if (!w || !actor || !target || actor.id === target.id) return null;
  const d = identityCanonFor(w, actor.id);
  if (!d) return null;
  const status = String(d.relationshipStatus || "").toLowerCase();
  if (isFakeDatingText(status)) return null;
  if (!/married|engaged|dating|relationship|partner/.test(status)) return null;
  if (d.faithful === false) return null;
  const partner = String(d.partner || "").trim();
  if (partner && identityNameMatches(partner, target)) return null;
  let snippet = "";
  try { snippet = String(connectionCanonSnippetAbout(w, actor, target, 700) || "").toLowerCase(); } catch (_) { snippet = ""; }
  if (/\b(?:wife|husband|spouse|married|fianc[eé]e?|girlfriend|boyfriend)\b|feles[eé]g|f[eé]rj|h[aá]zast[aá]rs|jegyes|bar[aá]tn[oő]j/.test(snippet) && !/\bex[- ]|volt (?:feles|f[eé]rj|bar[aá]t)/.test(snippet)) return null;
  return { status, partner };
}

function identityPronouns(c) {
  const g = String(c && c.gender || "").trim().toLowerCase();
  if (!g) return "";
  if (/non-?binary|nemb[ie]n[aá]ris|\bthey\b|genderfluid|agender/.test(g)) return "they/them";
  if (/female|woman|girl|\bshe\b|^n[őo]\b|^n[őo]$|l[aá]ny|asszony/.test(g)) return "she/her";
  if (/\bmale\b|^man\b|\bman\b|boy|\bhe\b|f[eé]rfi|fi[uú]/.test(g)) return "he/him";
  return "";
}

function identityCanonLine(w, c) {
  if (!w || !c) return "";
  const d = identityCanonFor(w, c.id) || {};
  const en = worldLanguage(w, w.meId) === "en";
  const pronouns = identityPronouns(c);
  const bits = [];
  if (pronouns) bits.push((en ? "pronouns: " : "névmások: ") + pronouns);
  if (Array.isArray(d.affiliations) && d.affiliations.length) {
    bits.push((en ? "belongs to: " : "tagja: ") + d.affiliations.map((a) => a.name + " (" + [a.kind, a.role].filter(Boolean).join(", ") + ")").join("; "));
  } else if (d.group) bits.push((en ? "group: " : "csoport: ") + d.group + (d.role ? " (" + d.role + ")" : ""));
  else if (d.role) bits.push((en ? "role: " : "szerep: ") + d.role);
  if (d.leader) bits.push((en ? "sensei/leader: " : "sensei/vezető: ") + d.leader);
  if (Array.isArray(d.teammates) && d.teammates.length) bits.push((en ? "teammates/students: " : "csapattársak/tanítványok: ") + d.teammates.slice(0, 5).join(", "));
  if (Array.isArray(d.rivals) && d.rivals.length) bits.push((en ? "rivals: " : "riválisok: ") + d.rivals.slice(0, 4).join(", "));
  if (Array.isArray(d.hates) && d.hates.length) bits.push((en ? "despises: " : "megveti: ") + d.hates.slice(0, 3).join(", "));
  const status = String(d.relationshipStatus || "").toLowerCase();
  if (isFakeDatingText(status)) {
    /* shown to everyone as the public version; the "fake" part lives only in the pair's own cards */
    bits.push((en ? "status: publicly dating " : "családi állapot: nyilvánosan együtt van vele: ") + (d.partner || "?"));
  } else if (status && status !== "unknown" && status !== "single") {
    bits.push((en ? "status: " : "családi állapot: ") + status + (d.partner ? (en ? " — partner: " : " — partner: ") + d.partner : "") + (d.faithful === false ? (en ? " (not faithful)" : " (nem hűséges)") : ""));
  } else if (status === "single") {
    bits.push(en ? "status: single" : "családi állapot: egyedülálló");
  }
  if (d.children) bits.push((en ? "children: " : "gyerekek: ") + d.children);
  if (d.age) bits.push((en ? "age: " : "kor: ") + d.age);
  const who = c.name + " [" + c.id + "]" + (isHuman(w, c.id) ? (en ? " — PLAYER" : " — JÁTÉKOS") : "");
  const nickInfo = nicknameInfo(c.nick);
  const call = isHuman(w, c.id)
    ? (en ? (pronouns === "she/her" ? " · call her: " : pronouns === "he/him" ? " · call him: " : " · call them: ") : " · így szólítsák: ") + ((nickInfo.plain && nickInfo.name) || String(c.name || "").split(/\s+/)[0]) +
      (nickInfo.name && !nickInfo.plain
        ? (en
          ? " · alias \"" + nickInfo.name + "\" (private note, never write it out: " + nickInfo.note + ") — only a speaker whose own sheet or card shows they know and use that name says it, as a plain name and never explained or in brackets; everyone else says " + (String(c.name || "").split(/\s+/)[0])
          : " · alias \"" + nickInfo.name + "\" (privát megjegyzés, soha ne írd ki: " + nickInfo.note + ") — csak az mondja, akinek a saját lapja/kártyája szerint ismeri és használja ezt a nevet, sima névként, magyarázat és zárójel nélkül; mindenki más így szólítja: " + (String(c.name || "").split(/\s+/)[0]))
        : "")
    : "";
  if (!d.oneLine && bits.length <= (pronouns ? 1 : 0) && !call) return pronouns ? "- " + who + " · " + bits.join(" · ") : "";
  return "- " + who + (d.oneLine ? " — " + d.oneLine : "") + (bits.length ? " · " + bits.join(" · ") : "") + call;
}

/* CLAUDE FIX R11: separate groups/settings must never blend into one storyline
   (a death game, a gang and a university house do not share a scoreboard). */
function worldGroupGlossary(w, scope = null) {
  const state = w && w.sim && w.sim.identityCanon;
  if (!state) return [];
  const groups = new Map();
  const norm = (x) => String(x || "").toLowerCase().replace(/^the\s+/, "").replace(/\s+/g, " ").trim();
  allSubjects(w).forEach((c) => {
    if (!c || !c.id || isMediaAccount(w, c.id)) return;
    const d = identityCanonFor(w, c.id);
    if (!d) return;
    const list = Array.isArray(d.affiliations) && d.affiliations.length ? d.affiliations : (d.group ? [{ name: d.group, kind: "", role: d.role }] : []);
    list.forEach((a) => {
      const key = norm(a.name);
      if (!key || key.length < 2) return;
      const row = groups.get(key) || { name: a.name, kinds: {}, members: [] };
      if (a.kind) row.kinds[a.kind] = (row.kinds[a.kind] || 0) + 1;
      row.members.push({ id: c.id, label: String(c.name || "").split(/\s+/)[0] + (a.role ? " (" + a.role + ")" : "") });
      groups.set(key, row);
    });
  });
  /* With a focused conversation only the groups of the people in it are listed. */
  const rows = [...groups.values()]
    .sort((a, b) => Math.min(6, b.members.length) - Math.min(6, a.members.length));
  return groupsForScope(rows, scope, 6)
    .slice(0, 14)
    .map((g) => {
      const kind = Object.entries(g.kinds).sort((x, y) => y[1] - x[1]).map(([k]) => k)[0] || "";
      return { name: g.name, kind, members: g.members.map((m) => m.label) };
    });
}

function worldGroupGlossaryCard(w, scope = null) {
  const rows = worldGroupGlossary(w, scope);
  if (!rows.length) return "";
  const en = worldLanguage(w, w.meId) === "en";
  return (en
    ? "WORLD GROUPS & SETTINGS — SEPARATE THINGS, NEVER MERGE THEM:\n"
    : "A VILÁG CSOPORTJAI ÉS HELYSZÍNEI — KÜLÖN DOLGOK, SOHA NE MOSD ÖSSZE ŐKET:\n") +
    rows.map((g) => "- " + g.name + (g.kind ? " = " + g.kind : "") + (g.members.length ? (en ? " · people: " : " · emberek: ") + g.members.join(", ") : "")).join("\n") +
    (en
      ? "\nRULES: each of these is its own thing and behaves only like its kind (a gang does gang things, a university house does campus life, a death game is a deadly game, not a sport). Never put different groups into one contest, league or scoreboard, never invent scores or rankings between them, and never move one group's events into another's setting unless the story explicitly connects them."
      : "\nSZABÁLYOK: mindegyik önálló dolog, és csak a saját fajtája szerint működik (a banda bandaként, az egyetemi ház campus-életként, a halálos játék halálos játékként, nem sportként). Különböző csoportokat soha ne tegyél egy versenybe, ligába vagy pontversenybe, ne találj ki köztük pontszámot vagy rangsort, és egyik csoport eseményeit se helyezd át a másik közegébe, hacsak a történet kifejezetten össze nem köti őket.");
}

/* CLAUDE FIX R16: group chats get exact identities and the members' real
   relationships to each other in a protected tail, so nobody mistakes the
   player for someone from a backstory and strangers do not "bro" each other. */
function conversationStripQuotedSegments(value) {
  return String(value || "")
    .replace(/["“„][^"”“„\n]{0,220}["”“]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function conversationReportedWordingQuestion(value) {
  const t =
    normalizeAddressText(
      conversationStripQuotedSegments(
        value
      )
    )
      .replace(/[’‘]/g, "'");

  return (
    /\b(?:why|what|how|miert|mit|hogyan|hogyhogy)\b/.test(t) &&
    /\b(?:call|called|calling|say|said|saying|write|wrote|written|comment|commented|mean|meant|hiv|hivtal|hivod|hivja|mond|mondtad|mondod|irta|irtad|komment)\w*/.test(t)
  );
}

function conversationPlayerRomanceToAddressee(value) {
  const raw =
    conversationStripQuotedSegments(
      value
    );

  const t =
    normalizeAddressText(
      raw
    )
      .replace(/[’‘]/g, "'");

  return (
    /\b(?:i\s+(?:love|want|need|miss|choose|like)\s+you|i(?:'m|\s+am)\s+into\s+you|love\s+you|miss\s+you|want\s+you|thinking\s+(?:of|about)\s+you|can'?t\s+stop\s+thinking\s+about\s+you|you(?:'re|\s+are)\s+(?:so\s+)?(?:hot|cute|pretty|beautiful|gorgeous|handsome|sexy|my\s+type)|you\s+look\s+(?:hot|cute|pretty|beautiful|gorgeous|handsome|sexy|amazing)|kiss\s+me|date\s+me|be\s+mine|come\s+over|marry\s+me)\b/.test(t) ||
    /\b(?:szeretlek|akarlak|hianyzol|kellesz|rad\s+gondolok|csokolj\s+meg|randizz\s+velem|gyere\s+at|legyel\s+az\s+enyem|te\s+vagy\s+(?:olyan\s+)?(?:dogos|szexi|szep|gyonyoru|cuki|helyes))\b/.test(t) ||
    /[😘😍🥰❤️❤💕💖😉😏💋🥵🫦]/u.test(raw)
  );
}

function conversationPlayerConflictToAddressee(value) {
  const t =
    normalizeAddressText(
      conversationStripQuotedSegments(
        value
      )
    )
      .replace(/[’‘]/g, "'");

  return (
    /\b(?:fuck\s+you|screw\s+you|shut\s+up|go\s+to\s+hell|piss\s+off|get\s+lost|back\s+off|i\s+(?:hate|despise)\s+you|i\s+can'?t\s+stand\s+you|you(?:'re|\s+are)\s+(?:a\s+)?(?:liar|bitch|slut|whore|idiot|loser|coward|pathetic|fake|trash|stupid|creep|psycho|freak)|i(?:'ll|\s+will)\s+(?:hit|kill|ruin)\s+you|watch\s+your\s+back|fight\s+me|try\s+me|leave\s+me\s+alone|don'?t\s+touch\s+me)\b/.test(t) ||
    /\b(?:kuss|huzz\s+el|tunj\s+el|utallak|gyulollek|ki\s+nem\s+allhatlak|te\s+(?:egy\s+)?(?:hazug|kurva|ribanc|idiota|vesztes|gyava|szanalmas|kamu|undorito|hulye)|meg(?:ollek|verlek)|hagyj\s+beken|szallj\s+le\s+rolam)\b/.test(t)
  );
}

function conversationPlayerConflictWithNamedPerson(w, value, targetId) {
  const target =
    charById(
      w,
      targetId
    );

  if (!target) return false;

  const raw =
    conversationStripQuotedSegments(
      value
    );

  const t =
    normalizeAddressText(
      raw
    )
      .replace(/[’‘]/g, "'");

  const aliases =
    characterAddressAliases(
      target
    )
      .map((alias) =>
        normalizeAddressText(
          String(alias || "")
            .replace(/^@/, "")
        )
      )
      .filter((alias) => alias.length >= 2);

  return aliases.some((alias) => {
    const core =
      escapeAddressRegex(
        alias
      );

    if (
      new RegExp(
        "\\b(?:i\\s+(?:hate|despise)\\s+|fuck\\s+|screw\\s+)" +
        core +
        "\\b",
        "i"
      ).test(
        t
      )
    ) {
      return true;
    }

    if (
      new RegExp(
        "\\b(?:utalom|gyulolom)\\s+" +
        core +
        "\\b",
        "i"
      ).test(
        t
      )
    ) {
      return true;
    }

    if (
      !/[?？]/.test(
        raw
      ) &&
      new RegExp(
        "\\b" +
        core +
        "\\s+(?:is|['’]s)\\s+(?:a\\s+)?(?:liar|bitch|slut|whore|idiot|loser|coward|pathetic|fake|trash|stupid|creep|psycho|freak)\\b",
        "i"
      ).test(
        t
      )
    ) {
      return true;
    }

    return false;
  });
}

function groupPlayerSemanticSocialSignals(
  w,
  value,
  addresseeId,
  memberIds
) {
  const ids =
    [...new Set(
      (memberIds || [])
        .map(String)
        .filter(Boolean)
    )]
      .filter((id) =>
        charById(
          w,
          id
        ) &&
        !isHuman(
          w,
          id
        )
      );

  const allowed =
    new Set(
      ids
    );

  const addressee =
    addresseeId &&
    allowed.has(
      String(
        addresseeId
      )
    )
      ? String(
          addresseeId
        )
      : "";

  const clean =
    conversationStripQuotedSegments(
      value
    );

  let romanceTargetId = "";
  let dramaTargetId = "";
  let nicknameTargetId = "";
  let nicknameHit = null;

  if (
    addressee &&
    conversationPlayerRomanceToAddressee(
      clean
    )
  ) {
    romanceTargetId =
      addressee;
  }

  if (!romanceTargetId) {
    const named =
      namedPeopleInText(
        w,
        clean,
        w.meId
      )
        .filter((id) =>
          allowed.has(
            String(
              id
            )
          )
        );

    romanceTargetId =
      named.find((id) => {
        try {
          return directDmPlayerSignalsRomanticAttentionToNamedPerson(
            clean,
            nameOfIn(
              w,
              id
            )
          );
        } catch (error) {
          return false;
        }
      }) || "";
  }

  if (
    addressee &&
    conversationPlayerConflictToAddressee(
      clean
    )
  ) {
    dramaTargetId =
      addressee;
  }

  if (!dramaTargetId) {
    dramaTargetId =
      namedPeopleInText(
        w,
        clean,
        w.meId
      )
        .filter((id) =>
          allowed.has(
            String(
              id
            )
          )
        )
        .find((id) =>
          conversationPlayerConflictWithNamedPerson(
            w,
            clean,
            id
          )
        ) || "";
  }

  if (
    addressee &&
    !conversationReportedWordingQuestion(
      value
    )
  ) {
    try {
      nicknameHit =
        hatedNicknameHit(
          w,
          w.meId,
          addressee,
          value
        );
    } catch (error) {
      nicknameHit = null;
    }

    if (nicknameHit) {
      nicknameTargetId =
        addressee;
    }
  }

  const rawJuice =
    publicSocialJuiceSignals(
      value
    );

  return {
    romanceTargetId,
    dramaTargetId,
    nicknameTargetId,
    nicknameHit,
    romance:
      romanceTargetId
        ? Math.max(
            24,
            Number(rawJuice.romance) || 0
          )
        : 0,
    drama:
      dramaTargetId
        ? Math.max(
            26,
            Number(rawJuice.drama) || 0
          )
        : 0,
    importance:
      Number(rawJuice.importance) || 0,
    embarrassment:
      Number(rawJuice.embarrassment) || 0,
    tags:
      Array.isArray(rawJuice.tags)
        ? rawJuice.tags
        : [],
  };
}

function groupChatPlayerMoveLines(w, ids, move, en) {
  if (!move || !move.text || !w.meId) return "";

  const signal =
    groupPlayerSemanticSocialSignals(
      w,
      move.text,
      move.targetId || "",
      ids
    );

  const player =
    nameOfIn(
      w,
      w.meId
    );

  const lines = [];

  if (
    signal.romanceTargetId
  ) {
    const target =
      nameOfIn(
        w,
        signal.romanceTargetId
      );

    ids
      .filter((id) =>
        id !==
        signal.romanceTargetId
      )
      .forEach((id) => {
        let crush = false;

        try {
          crush =
            relationshipCrushActive(
              w,
              id,
              w.meId
            );
        } catch (error) {
          crush = false;
        }

        if (!crush) return;

        const level =
          emotionalIntensity(
            w,
            id,
            w.meId,
            "jealous"
          );

        lines.push(
          en
            ? "- " + nameOfIn(w, id) + " has feelings for " + player + " and just watched her/him flirt with " + target + " right here: " + (level === "extreme" ? "open, possessive jealousy at full intensity" : "visible jealousy") + " in their own style."
            : "- " + nameOfIn(w, id) + " érez valamit " + player + " iránt, és most itt látta flörtölni " + target + "-val/vel: " + (level === "extreme" ? "nyílt, birtokló féltékenység teljes erővel" : "látható féltékenység") + ", a saját stílusában."
        );
      });
  }

  if (
    signal.dramaTargetId
  ) {
    const targetId =
      signal.dramaTargetId;

    const target =
      nameOfIn(
        w,
        targetId
      );

    ids
      .filter((id) =>
        id !==
        targetId
      )
      .forEach((id) => {
        const loyal =
          socialPersonClosenessStake(
            w,
            id,
            targetId
          );

        if (loyal >= 2) {
          lines.push(
            en
              ? "- " + nameOfIn(w, id) + " is close to " + target + " and takes " + target + "'s side against " + player + "."
              : "- " + nameOfIn(w, id) + " közel áll " + target + "-hoz/hez, és " + target + " oldalára áll " + player + " ellen."
          );
        } else if (
          relationshipIsHostile(
            w,
            id,
            targetId
          )
        ) {
          lines.push(
            en
              ? "- " + nameOfIn(w, id) + " can't stand " + target + " and enjoys seeing " + player + " go after them."
              : "- " + nameOfIn(w, id) + " ki nem állhatja " + target + "-t, és élvezi, hogy " + player + " nekimegy."
          );
        }
      });
  }

  if (
    signal.nicknameTargetId &&
    signal.nicknameHit
  ) {
    const target =
      nameOfIn(
        w,
        signal.nicknameTargetId
      );

    lines.push(
      en
        ? "- " + player + " just called " + target + " “" + signal.nicknameHit.nickname + "”, a name " + target + " hates — " + target + " reacts to it" + (signal.nicknameHit.reaction ? " (" + signal.nicknameHit.reaction + ")" : "") + "."
        : "- " + player + " épp “" + signal.nicknameHit.nickname + "”-nak/nek hívta " + target + "-t, amit utál — reagál rá" + (signal.nicknameHit.reaction ? " (" + signal.nicknameHit.reaction + ")" : "") + "."
    );
  }

  if (!lines.length) return "";

  return (
    en
      ? "WHAT THE OTHERS JUST SAW — THEY REACT TO IT NOW:\n"
      : "AMIT A TÖBBIEK MOST LÁTTAK — MOST REAGÁLNAK RÁ:\n"
  ) +
    lines
      .slice(0, 5)
      .join("\n") +
    "\n";
}

function groupChatSocialTail(w, aiIds, move = null) {
  if (!w) return "";
  const en = worldLanguage(w, w.meId) === "en";
  const ids = [...new Set((aiIds || []).filter(Boolean).map(String))].filter((id) => charById(w, id) && !isHuman(w, id)).slice(0, 7);
  const player = w.player || charById(w, w.meId) || {};
  const playerCall = plainNickname(player.nick) || String(player.name || "").split(/\s+/)[0];
  const relLine = (a, b) => {
    const r = getRel(w, a, b) || EMPTY_REL;
    const bond = r.bond || r.type ? localizedBond(r.bond || r.type, en ? "en" : "hu") : (en ? "no special bond" : "nincs külön kötelék");
    return "- " + nameOfIn(w, a) + " → " + nameOfIn(w, b) + ": " + bond + " (" + (Number(r.score) || 0) + ")" + (r.mood ? " · " + String(r.mood).slice(0, 60) : "");
  };
  const lines = [];
  ids.forEach((a) => ids.forEach((b) => { if (a !== b && lines.length < 30) lines.push(relLine(a, b)); }));
  ids.forEach((a) => { if (w.meId && lines.length < 40) lines.push(relLine(a, w.meId)); });
  let members = "";
  try { members = whoIsWhoCard(w, ids); } catch (error) { members = ""; }
  return "\n\n" + PROTECTED_TAIL_MARKER + "\n" + (en
    ? "GROUP CHAT — EXACT IDENTITIES:\n- The player is " + player.name + " [" + w.meId + "], call her/him \"" + playerCall + "\". Every message from [" + w.meId + "] is " + player.name + " — never anyone else (not a friend, rival or name from somebody's backstory).\n"
    : "GROUP CHAT — PONTOS SZEMÉLYAZONOSSÁGOK:\n- A játékos " + player.name + " [" + w.meId + "], szólítsák így: \"" + playerCall + "\". Minden [" + w.meId + "] üzenet " + player.name + " — soha nem valaki más (nem egy barát, rivális vagy név valakinek a hátteréből).\n") +
    (members ? members + "\n" : "") +
    groupChatPlayerMoveLines(w, ids, move, en) +
    (en ? "RELATIONSHIPS BETWEEN THE MEMBERS (each from their own side — these decide the tone):\n" : "KAPCSOLATOK A TAGOK KÖZÖTT (mindenki a saját oldaláról — ezek határozzák meg a hangot):\n") +
    lines.join("\n") + "\n" +
    (en
      ? "RULES: talk to each other exactly as these relationships say — strangers and acquaintances do not call each other bro or banter like old friends; rivals snipe hard; enemies are openly hostile at full intensity (contempt, insults, threats in their own style — never polite); someone with feelings for a person turns visibly jealous when others get close to them; only real friends joke around like friends. Play every character 1:1 from their own sheet — personality, speech style, history — never one generic voice."
      : "SZABÁLYOK: pontosan úgy beszéljenek egymással, ahogy ezek a kapcsolatok mondják — idegenek és ismerősök nem „bro”-znak és nem haverkodnak; riválisok keményen szurkálódnak; ellenségek nyíltan, teljes intenzitással ellenségesek (megvetés, sértés, fenyegetés a saját stílusukban — sosem udvariasan); aki érez valamit valaki iránt, látványosan féltékeny lesz, ha más közel kerül hozzá; csak valódi barátok poénkodnak barátként. Minden karaktert 1:1 a saját lapja szerint játssz — személyiség, beszédstílus, történet —, soha ne egy általános hangon.");
}

function whoIsWhoCard(w, ids) {
  if (!w) return "";
  const list = (Array.isArray(ids) ? ids : [ids]).filter(Boolean).map(String);
  if (w.meId) list.unshift(String(w.meId));
  const seen = new Set();
  const lines = [];
  list.forEach((id) => {
    if (seen.has(id) || lines.length >= 14) return;
    seen.add(id);
    const c = charById(w, id);
    if (!c || isMediaAccount(w, id)) return;
    const line = identityCanonLine(w, c);
    if (line) lines.push(line);
  });
  if (!lines.length) return "";
  const en = worldLanguage(w, w.meId) === "en";
  return en
    ? "WHO IS WHO — CANON FROM EACH PERSON'S OWN SHEET (public facts; everyone in town knows them):\n" + lines.join("\n") +
      "\nRULES: Everyone knows which dojo/team/group each person belongs to, who their sensei/leader is, who their teammates are and who is married. Members of rival groups treat each other as rivals unless a personal bond written on their own sheet says otherwise. A married/committed person is loyal to their partner: they don't start flirting, and advances from others meet resistance that fits their personality (guilt, deflection, awkwardness, a firm reminder of their partner). Only tension built up slowly over time can create cracks, and they struggle with it. Adults who teach, coach or lead younger people keep a professional distance from them unless their sheet says otherwise — and when the sheets DO give such a pair more (attraction, tension, a secret), that layer is real: play it with the weight of the line they should not cross. Use each person's pronouns exactly as listed — never swap he/she or him/her. Address the player by her/his real name or the given nickname, never by another character's name."
    : "KI KICSODA — KÁNON MINDENKI SAJÁT LAPJÁRÓL (nyilvános tények, a városban mindenki tudja):\n" + lines.join("\n") +
      "\nSZABÁLYOK: Mindenki tudja, ki melyik dojóhoz/csapathoz/csoporthoz tartozik, ki a senseie/vezetője, kik a csapattársai és ki házas. Rivális csoportok tagjai riválisként kezelik egymást, hacsak a saját lapjukon leírt személyes kötődés mást nem mond. Házas/elkötelezett ember lojális a partneréhez: nem kezdeményez flörtöt, és a közeledésre a személyiségéhez illő ellenállással reagál (bűntudat, hárítás, zavar, a partnerére való emlékeztetés). Csak lassan, idővel felépülő feszültség okozhat repedést, és ő vívódik vele. Fiatalabbakat tanító/edző/vezető felnőtt szakmai távolságot tart velük, hacsak a lapja mást nem mond. Mindenkire a megadott névmással hivatkozz (angol szövegben he/him, she/her) — soha ne keverd a nemeket. A játékost a valódi nevén vagy a megadott becenevén szólítsák, soha ne egy másik karakter nevén."
}





/* CLAUDE FIX R23: CHARACTER BIBLE. Every AI character's full sheet is read once
   more (deep model) into a compact "sheet canon": the person at full intensity,
   their defining extremes (obsessed, cruel, possessive...) with the target and
   how it shows, their backstory in order, their key people, what they would
   never do and their typical lines. This card travels with the speaker into
   every prompt, so the story is known 1:1 and the personality is not softened. */
const CHARACTER_BIBLE_VERSION = "3"; /* R70: regenerate from complete raw sheet */
const CHARACTER_BIBLE_MIN_GAP_MS = 15 * 1000;
const CHARACTER_BIBLE_RETRY_MS = 10 * 60 * 1000;

function characterBibleState(w) {
  const sim = ensureSimState(w);
  if (!sim) return null;
  if (!sim.characterBible || typeof sim.characterBible !== "object" || Array.isArray(sim.characterBible)) sim.characterBible = {};
  return sim.characterBible;
}

function characterBibleSource(c) {
  if (!c) return "";
  const parts = deepCharacterSheetSourceParts(c);
  /* R70: character bible is generated once from the complete raw sheet. */
  return [stripTechnicalSheetRows(parts.publicText), stripTechnicalSheetRows(parts.privateText)].filter(Boolean).join("\n");
}

function characterBibleFor(w, id) {
  const state = w && w.sim && w.sim.characterBible;
  const row = state && id ? state[id] : null;
  return row && row.data && typeof row.data === "object" ? row.data : null;
}

function characterBibleCard(w, c, budget = 2400) {
  if (!w || !c) return "";
  const d = characterBibleFor(w, c.id);
  if (!d) return "";
  const en = worldLanguage(w, w.meId) === "en";
  const name = String(c.name || c.id || "").toUpperCase();
  const lines = [
    en
      ? "SHEET CANON — PERSONALITY & HISTORY OF " + name + " (from their own sheet; know it 1:1, play it at FULL intensity; private unless it is public knowledge):"
      : "LAPKÁNON — " + name + " SZEMÉLYISÉGE ÉS TÖRTÉNETE (a saját lapjáról; 1:1 tudd, TELJES intenzitással játszd; privát, hacsak nem közismert):",
  ];
  if (d.core) lines.push((en ? "CORE: " : "LÉNYEG: ") + d.core);
  try {
    const nick = characterNicknameLines(w, c, en);
    if (nick) lines.push(nick);
  } catch (error) { /* ignore */ }
  if (Array.isArray(d.extremes) && d.extremes.length) {
    lines.push(en ? "DEFINING EXTREMES — show them every time they are relevant, never tone them down:" : "MEGHATÁROZÓ SZÉLSŐSÉGEK — mindig mutasd, amikor számít, soha ne tompítsd:");
    d.extremes.forEach((x) => lines.push("- " + x.trait + (x.toward ? " → " + x.toward : "") + (x.shows ? ": " + x.shows : "")));
  }
  if (Array.isArray(d.history) && d.history.length) {
    lines.push(en ? "HISTORY — their own past, in order; they remember it exactly and never contradict it or invent another version:" : "TÖRTÉNET — a saját múltja, sorrendben; pontosan emlékszik rá, soha nem mond ellent neki és nem talál ki más változatot:");
    d.history.forEach((x, i) => lines.push((i + 1) + ". " + x));
  }
  if (Array.isArray(d.people) && d.people.length) {
    lines.push(en ? "KEY PEOPLE:" : "FONTOS EMBEREK:");
    d.people.forEach((x) => lines.push("- " + x.name + (x.is ? " (" + x.is + ")" : "") + (x.feels ? ": " + x.feels : "")));
  }
  if (Array.isArray(d.never) && d.never.length) lines.push((en ? "NEVER: " : "SOHA: ") + d.never.join(" · "));
  if (Array.isArray(d.phrases) && d.phrases.length) lines.push((en ? "TYPICAL LINES (imitate the pattern, do not repeat verbatim): " : "JELLEMZŐ MONDATOK (a mintát kövesd, ne szó szerint ismételd): ") + d.phrases.map((x) => "\"" + x + "\"").join(" · "));
  let out = lines.join("\n");
  if (out.length > budget) {
    /* keep the head (core + extremes) whole; the tail lines go first */
    out = out.slice(0, Math.max(400, budget - 20)).replace(/\n[^\n]*$/, "") + "\n…";
  }
  return out;
}

/* CLAUDE FIX R28: NICKNAMES FROM THE SHEETS. "X calls Y <nickname>" (on either
   person's sheet) is used in play, and "Y hates being called that" makes Y
   react — and costs X a little with Y every time. */
function nicknameMatchesPerson(name, person) {
  if (!person) return false;
  try { return identityNameMatches(name, person); } catch (error) { return false; }
}

function nicknamesUsedBy(w, speakerId, targetId) {
  const speaker = charById(w, speakerId), target = charById(w, targetId);
  if (!speaker || !target || speakerId === targetId) return [];
  const out = [];
  const own = characterBibleFor(w, speakerId);
  (own && Array.isArray(own.callsOthers) ? own.callsOthers : []).forEach((x) => {
    if (x && x.nickname && nicknameMatchesPerson(x.person, target)) out.push({ nickname: x.nickname, tone: x.tone || "" });
  });
  const theirs = characterBibleFor(w, targetId);
  (theirs && Array.isArray(theirs.calledBy) ? theirs.calledBy : []).forEach((x) => {
    if (x && x.nickname && x.by && nicknameMatchesPerson(x.by, speaker) && !out.some((y) => y.nickname.toLowerCase() === x.nickname.toLowerCase())) {
      out.push({ nickname: x.nickname, tone: /hate|ut[aá]l|gy[uű]l[oö]l/.test(x.feeling || "") ? "they hate it" : (x.feeling || "") });
    }
  });
  return out.slice(0, 4);
}

function hatedNicknameHit(w, speakerId, targetId, text) {
  const value = String(text || "").toLowerCase();
  if (!value || !targetId) return null;
  const d = characterBibleFor(w, targetId);
  const speaker = charById(w, speakerId);
  const rows = d && Array.isArray(d.calledBy) ? d.calledBy : [];
  for (const x of rows) {
    if (!x || !x.nickname || !/hate|ut[aá]l|gy[uű]l[oö]l|despis|can['’]?t stand|ki nem [aá]llhat|annoy|ideges[ií]t|irrit/.test(String(x.feeling || "") + " " + String(x.reaction || ""))) continue;
    if (/secretly likes|titokban/.test(String(x.feeling || ""))) continue;
    if (x.by && speaker && !nicknameMatchesPerson(x.by, speaker)) continue;
    const nick = String(x.nickname).toLowerCase().trim();
    if (nick.length < 2) continue;
    const at = value.indexOf(nick);
    if (at < 0) continue;
    const before = at === 0 ? " " : value.charAt(at - 1), after = value.charAt(at + nick.length) || " ";
    if (/[\p{L}\p{N}]/u.test(before) || /[\p{L}\p{N}]/u.test(after)) continue;
    return x;
  }
  return null;
}

function characterNicknameLines(w, c, en) {
  if (!w || !c) return "";
  const lines = [];
  const people = allSubjects(w).filter((p) => p && p.id && p.id !== c.id && !isMediaAccount(w, p.id));
  people.forEach((p) => {
    nicknamesUsedBy(w, c.id, p.id).forEach((x) => lines.push((en ? "you call " : "így szólítod: ") + p.name + " → \"" + x.nickname + "\"" + (x.tone ? " (" + x.tone + ")" : "")));
  });
  const d = characterBibleFor(w, c.id);
  const calledBy = d && Array.isArray(d.calledBy) ? d.calledBy : [];
  const own = [];
  calledBy.forEach((x) => {
    if (!x || !x.nickname) return;
    own.push("\"" + x.nickname + "\"" + (x.by ? (en ? " from " : " – ") + x.by : "") + ": " + (x.feeling || "") + (x.reaction ? (en ? " — reaction: " : " — reakció: ") + x.reaction : ""));
  });
  const out = [];
  if (lines.length) out.push((en ? "NICKNAMES YOU USE — use them naturally when you address these people, as your sheet says (even if they hate it): " : "BECENEVEK, AMIKET HASZNÁLSZ — szólítsd így őket természetesen, ahogy a lapod mondja (akkor is, ha utálják): ") + lines.slice(0, 6).join(" · "));
  if (own.length) out.push((en ? "WHAT OTHERS CALL YOU — when someone uses one of these, react exactly as written: " : "AHOGY TÉGED HÍVNAK — ha valaki így szólít, pontosan így reagálj: ") + own.slice(0, 5).join(" · "));
  /* R77: a pet name on the sheet belongs to the one person it names */
  out.push(en
    ? "A name or pet name on your sheet belongs ONLY to the person it names there. Never call anyone else by it — not the player, not a crush, not anyone who reminds you of them."
    : "A lapodon szereplő név vagy becenév CSAK ahhoz az egy emberhez tartozik, akit ott jelöl. Senki mást ne szólíts így — a játékost sem, a crushodat sem, senkit, aki rá emlékeztet.");
  return out.join("\n");
}

function applyHatedNicknameConsequence(w, event) {
  if (!w || !event || event.factLevel !== "observed") return;
  const type = String(event.type || "");
  if (!["comment", "reply", "post", "group-message", "dm-message", "dm"].includes(type)) return;
  const actorId = String(event.actorId || "");
  if (!actorId) return;
  (event.targetIds || []).map(String).filter((id) => id && id !== actorId && !isHuman(w, id)).slice(0, 4).forEach((targetId) => {
    const hit = hatedNicknameHit(w, actorId, targetId, event.text);
    if (!hit) return;
    const rel = getRel(w, targetId, actorId) || EMPTY_REL;
    const oldScore = Number(rel.score) || 0;
    const next = Math.max(-100, oldScore - 2);
    const en = worldLanguage(w, w.meId) === "en";
    setRel(w, targetId, actorId, {
      score: next,
      mood: en ? "annoyed at being called \"" + hit.nickname + "\"" : "idegesíti, hogy \"" + hit.nickname + "\"-nak/nek hívják",
    });
    groundedEventLog(w, "relationship-change", "applied",
      nameOfIn(w, targetId) + " → " + nameOfIn(w, actorId) + ": -2 (called \"" + hit.nickname + "\", which " + nameOfIn(w, targetId) + " hates)",
      type + ":" + String(event.refId || event.id || ""));
    /* the target answers it in the same thread (cooldown per pair) */
    const sim = ensureSimState(w);
    sim.nicknameReactAt = sim.nicknameReactAt && typeof sim.nicknameReactAt === "object" ? sim.nicknameReactAt : {};
    const key = targetId + ">" + actorId;
    if ((type === "comment" || type === "reply") && event.meta && event.meta.postId && event.meta.commentId &&
        now() - (Number(sim.nicknameReactAt[key]) || 0) > 20 * 60 * 1000 && typeof simEnqueue === "function") {
      sim.nicknameReactAt[key] = now();
      simEnqueue(w, mkAction("reply", "hated-nickname:" + String(event.refId || event.id) + ":" + targetId, {
        postId: event.meta.postId, commentId: event.meta.commentId, targetId, trigger: "hated-nickname",
        dynamic: "hated-nickname", dynamicOtherId: actorId,
      }, actorId === w.meId ? "player-event" : "event"));
    }
  });
}

function characterBibleDueAction(w) {
  if (!w) return null;
  const state = characterBibleState(w);
  const sim = ensureSimState(w);
  if (!state || !sim) return null;
  if (now() - Number(sim.characterBibleLastAt || 0) < CHARACTER_BIBLE_MIN_GAP_MS) return null;
  const me = w.meId;
  const closeness = (c) => {
    if (!me) return 0;
    const a = getRel(w, c.id, me) || EMPTY_REL;
    const b = getRel(w, me, c.id) || EMPTY_REL;
    return Math.abs(Number(a.score) || 0) + Math.abs(Number(b.score) || 0) + (a.bond || b.bond ? 50 : 0);
  };
  const list = allSubjects(w)
    .filter((c) => c && c.id && !isMediaAccount(w, c.id))
    .sort((x, y) => (isHuman(w, y.id) ? 1 : 0) - (isHuman(w, x.id) ? 1 : 0) || closeness(y) - closeness(x));
  for (const c of list) {
    const src = characterBibleSource(c);
    if (src.trim().length < 40) continue;
    const hash = simsSocialStableHash(CHARACTER_BIBLE_VERSION + "\n" + src);
    const row = state[c.id];
    if (row && row.hash === hash) continue;
    if (row && row.failedAt && row.failedHash === hash && now() - Number(row.failedAt) < CHARACTER_BIBLE_RETRY_MS) continue;
    return mkAction("character-bible", "character-bible:" + c.id + ":" + hash, { charId: c.id, hash }, "memory");
  }
  return null;
}

async function runCharacterBibleAction(view, update, action) {
  const charId = String(action.payload && action.payload.charId || "");
  const c = charById(view, charId);
  update((n) => { ensureSimState(n).characterBibleLastAt = now(); });
  if (!c) return null;
  const src = characterBibleSource(c);
  const hash = simsSocialStableHash(CHARACTER_BIBLE_VERSION + "\n" + src);
  const en = worldLanguage(view, view.meId) === "en";
  const lang = en ? "English" : "Hungarian";
  const prompt = [
    "CHARACTER BIBLE — read this ONE character sheet completely, every section and every line, then extract how to play this person 1:1.",
    "Rules: only what the sheet states or clearly implies; never invent; never fall back on the original fandom or a generic type. Keep the sheet's INTENSITY: if the sheet says obsessed, write obsessed (not 'interested'); cruel stays cruel, possessive stays possessive, cold stays cold. Do not soften or moralise.",
    "",
    "CHARACTER SHEET (" + String(c.name || charId) + "):",
    src,
    "",
    "Fields (write in " + lang + "; quote typical phrases in their original language):",
    "- core: max 600 characters — who this person is at full intensity right now: the 3-5 traits that define them, how they behave in public vs in private.",
    "- extremes: their strongest traits, fixations and feelings exactly as extreme as the sheet (obsession, possessiveness, jealousy, cruelty, hatred, devotion, arrogance, fear...). Each: trait, toward (person/group it targets, or empty), shows (how it VISIBLY shows in messages, comments and actions — concrete behaviour). Max 6.",
    "- history: the key events of their backstory IN ORDER, each one short line with names, places and what happened, and how it marked them. Max 12, each max 170 characters.",
    "- people: the most important people on the sheet. Each: name, is (what they are to them), feels (how they feel and act toward them). Max 10.",
    "- never: things this person would never do or say, from the sheet. Max 6.",
    "- phrases: up to 4 typical lines or words they use (from the sheet, or very close to how the sheet describes their speech).",
    "- callsOthers: nicknames / pet names / mocking names THIS person uses for specific other people, exactly as the sheet states. Each: person (name), nickname (exact spelling), tone (affectionate | teasing | mocking | possessive | formal). Max 8. Empty if the sheet says nothing.",
    "- calledBy: names or nicknames OTHERS use for THIS person, and how THIS person feels about each, exactly as the sheet states. Each: by (who uses it; empty = anyone), nickname (exact spelling), feeling (hates | likes | tolerates | secretly likes), reaction (how they react when called that). Max 6. Empty if the sheet says nothing.",
    "",
    "JSON ONLY:",
    '{"core":"","extremes":[{"trait":"","toward":"","shows":""}],"history":[""],"people":[{"name":"","is":"","feels":""}],"never":[""],"phrases":[""],"callsOthers":[{"person":"","nickname":"","tone":""}],"calledBy":[{"by":"","nickname":"","feeling":"","reaction":""}]}',
  ].join("\n");
  let out = null;
  try {
    out = await askWorldJSON(view, SHEET_ANALYST_SYSTEM, prompt, { maxTokens: 3500, priority: 5, source: "character-bible", quality: "deep", timeoutMs: 120000 });
  } catch (error) {
    update((n) => {
      const state = characterBibleState(n);
      state[charId] = { ...(state[charId] || {}), failedAt: now(), failedHash: hash };
      groundedEventLog(n, "character-bible", "failed", c.name + ": " + String(error && error.message || error || "AI error"), "sheet:" + charId);
    });
    return null;
  }
  if (!out || typeof out !== "object" || out.skip === true || !("core" in out || "extremes" in out || "history" in out)) {
    update((n) => {
      const state = characterBibleState(n);
      state[charId] = { ...(state[charId] || {}), failedAt: now() - CHARACTER_BIBLE_RETRY_MS + 3 * 60 * 1000, failedHash: hash };
    });
    return null;
  }
  const clean = (v, max) => normalizeGeneratedSocialText(String(v === undefined || v === null ? "" : (typeof v === "object" ? (v.text || v.name || "") : v)))
    .replace(/\s+/g, " ").trim().slice(0, max);
  const list = (v, max, each) => (Array.isArray(v) ? v : (v ? [v] : [])).map((x) => clean(x, each)).filter(Boolean).slice(0, max);
  const data = {
    core: clean(out.core, 700),
    extremes: (Array.isArray(out.extremes) ? out.extremes : []).filter((x) => x && typeof x === "object" && String(x.trait || "").trim())
      .slice(0, 6).map((x) => ({ trait: clean(x.trait, 60), toward: clean(x.toward, 60), shows: clean(x.shows, 220) })),
    history: list(out.history, 12, 200),
    people: (Array.isArray(out.people) ? out.people : []).filter((x) => x && typeof x === "object" && String(x.name || "").trim())
      .slice(0, 10).map((x) => ({ name: clean(x.name, 60), is: clean(x.is, 70), feels: clean(x.feels, 170) })),
    never: list(out.never, 6, 140),
    phrases: list(out.phrases, 4, 140),
    callsOthers: (Array.isArray(out.callsOthers) ? out.callsOthers : []).filter((x) => x && typeof x === "object" && String(x.nickname || "").trim() && String(x.person || "").trim())
      .slice(0, 8).map((x) => ({ person: clean(x.person, 60), nickname: clean(x.nickname, 40), tone: clean(x.tone, 30).toLowerCase() })),
    calledBy: (Array.isArray(out.calledBy) ? out.calledBy : []).filter((x) => x && typeof x === "object" && String(x.nickname || "").trim())
      .slice(0, 6).map((x) => ({ by: clean(x.by, 60), nickname: clean(x.nickname, 40), feeling: clean(x.feeling, 30).toLowerCase(), reaction: clean(x.reaction, 160) })),
  };
  if (!data.core && !data.extremes.length && !data.history.length) {
    update((n) => {
      const state = characterBibleState(n);
      state[charId] = { ...(state[charId] || {}), failedAt: now(), failedHash: hash };
    });
    return null;
  }
  update((n) => {
    const state = characterBibleState(n);
    state[charId] = { hash, at: now(), data };
    const live = charById(n, charId);
    groundedEventLog(n, "character-bible", "applied",
      (live ? live.name : c.name) + ": " + data.extremes.map((x) => x.trait + (x.toward ? " → " + x.toward : "")).join(", ") + (data.history.length ? " · " + data.history.length + " history beats" : ""),
      "sheet:" + charId);
  });
  return "character-bible";
}

/* CLAUDE FIX R31: CREATIVE RELATIONSHIP LABELS. Every directed relationship
   an AI character has gets its own short, specific label ("can't-look-away
   obsession", "sparring partner with a grudge") — first from the sheets, and
   rewritten by the AI every time the relationship actually moves (new event,
   new mood, a real score jump), so it never stays a generic category. */





















async function runSimulationAction(view, update, action, addImage) {

  if (action && action.type === "relationship-reading") {
    return runRelationshipReadingAction(view, update, action);
  }


  if (action && action.type === "character-bible") {
    return runCharacterBibleAction(view, update, action);
  }

  if (action && action.type === "npc-pair-reaction") {
    const eventId = String(action.payload && action.payload.eventId || "");
    const sourceEvent = (view.socialEvents || []).find((row) => row && (String(row.id || "") === eventId || String(row.refId || "") === eventId));
    if (!sourceEvent || !groundedEventIsRecordedFact(view, sourceEvent)) {
      update((n) => groundedEventLog(n, "npc-pair-reaction", "blocked", "Reaction blocked: concrete source event not found.", "event:" + (eventId || "missing")));
      return null;
    }
  }
  const isPopup = action && action.type === "world-full" && String(action.payload && action.payload.trigger || "") === "popup-choice";
  const isFollowBack = action && action.type === "dm" && action.payload && action.payload.groundedFollowBackBotId;
  if (isPopup) update((n) => groundedEventLog(n, "popup-choice-followup", "started", "Popup follow-up started: relationship/feed/gossip pipeline.", "popup:" + String(action.payload.popupEventId || "")));
  let result;
  try {
    result = await legacyGroundedRunSimulationAction(view, update, action, addImage);
  } catch (error) {
    if (action && action.type === "world-full" && String(action.payload && action.payload.trigger || "") === "player-post") {
      update((n) => groundedEventLog(n, "player-post-world", "failed", "Feed refresh after your post failed: " + String(error && error.message || error || "Unknown failure"), "post:" + String(action.payload.postId || "")));
    }
    /* CLAUDE FIX R13: an event-driven feed refresh (post / scene / popup) that failed
       — server restart, timeout, busy provider — is retried once 30 s later. */
    const refreshTrigger = String(action && action.payload && action.payload.trigger || "");
    if (action && action.type === "world-full" && ["player-post", "roleplay-ended", "popup-choice"].includes(refreshTrigger) && !(action.payload && action.payload.retry)) {
      setTimeout(() => {
        update((n) => {
          simEnqueue(n, mkAction("world-full", String(action.key || "event-world") + ":retry", { ...(action.payload || {}), retry: 1 }, "player-event"));
          groundedEventLog(n, "feed-refresh", "retry", "Feed refresh (" + refreshTrigger + ") queued again after a failure.", "retry:" + String(action.key || ""));
        });
      }, 30000);
    }
    if (isPopup || isFollowBack) update((n) => groundedEventLog(n, isPopup ? "popup-choice-followup" : "follow-not-returned", "failed", String(error && error.message || error || "Unknown failure"), isPopup ? "popup:" + String(action.payload.popupEventId || "") : "follow:" + String(action.payload.groundedFollowBackBotId || "")));
    if (isFollowBack) update((n) => groundedFollowBackAttemptFailed(n, String(action.payload.groundedFollowBackBotId || ""), String(error && error.message || error || "error")));
    throw error;
  }
  if (isFollowBack) {
    update((n) => {
      const state = groundedRuntime(n);
      const botId = String(action.payload.groundedFollowBackBotId || "");
      if (result && result !== "dm-deferred") {
        delete state.pendingFollowBack[botId];
        const doneTrigger = String(action.payload.trigger || "follow-not-returned");
        groundedEventLog(n, doneTrigger, "success", doneTrigger === "player-unfollowed" ? "Unfollow reaction DM generated." : "Unreturned-follow DM generated.", "follow:" + botId + ">" + String(n.meId || ""));
      } else {
        groundedFollowBackAttemptFailed(n, botId, result === "dm-deferred" ? "deferred" : "no message returned");
      }
    });
  }
  if (isPopup) {
    update((n) => {
      const popupId = String(action.payload.popupEventId || "");
      const popup = (n.popupEvents || []).find((e) => e && String(e.id) === popupId);
      let gossip = null;
      try {
        if (popup && popup.gossipEligible !== false && typeof ensureEventDrivenGossipPost === "function") gossip = ensureEventDrivenGossipPost(n, "popup-choice", { popupEventId: popupId, choiceId: action.payload.choiceId || "" });
      } catch (error) { console.warn("[popup-followup] gossip safeguard failed", error); }
      const freshPosts = (n.posts || []).filter((p) => p && !isHuman(n, p.authorId) && now() - (Number(p.ts) || 0) < 2 * 60 * 1000).length;
      groundedEventLog(n, "popup-choice-followup", result ? "success" : "partial", "Popup follow-up finished; fresh AI posts=" + freshPosts + "; gossip=" + Boolean(gossip) + ".", "popup:" + popupId, { freshPosts, gossip: Boolean(gossip), actionResult: String(result || "") });
    });
  }
  return result;
}

function groundedRegisterIncomingDm(w, event) {
  const actorId = String(event && event.actorId || "");
  const humanId = String((event && event.targetIds || []).find((id) => isHuman(w, id)) || "");
  if (!actorId || !humanId || isHuman(w, actorId)) return;
  const state = groundedRuntime(w);
  state.dmUnread[actorId] = (Number(state.dmUnread[actorId]) || 0) + 1;
  const text = String(event.text || "");
  groundedEventLog(w, "dm", "received", nameOfIn(w, actorId) + " sent a DM.", groundedSourceRef(event), { actorId, humanId });
  const bridgeInvite = (w.scenes || []).some((sc) => sc && sc.chatBridge && String(sc.initiatedBy || "") === actorId && sc.invitationStatus === "pending" && now() - (Number(sc.invitedAt) || 0) < 5 * 60 * 1000);
  if (!bridgeInvite && groundedLooksLikeInvitation(text)) {
    const existing = (w.invitations || []).find((inv) => inv && inv.status === "pending" && inv.fromId === actorId && inv.sourceRef === groundedSourceRef(event));
    if (!existing) {
      w.invitations.unshift({ id: "inv_" + uid(), fromId: actorId, toId: humanId, createdAt: now(), when: groundedExtractInviteWhen(text), where: groundedExtractInviteWhere(text), context: text.slice(0, 800), sourceRef: groundedSourceRef(event), status: "pending" });
      groundedEventLog(w, "invitation", "received", "Invitation received from " + nameOfIn(w, actorId) + ".", groundedSourceRef(event));
    }
  }
}

/* CLAUDE FIX R8 (9.4): only a real invitation addressed to the player counts —
   "how was the party?" or "coffee is my religion" is not one. */
function groundedLooksLikeInvitation(text) {
  const s = String(text || "").toLowerCase();
  if (!s.trim()) return false;
  const en = /\b(?:come\s+(?:over|with\s+me|along|by|to\s+(?:my|the|our|this)\b)|join\s+(?:me|us)\b|meet\s+(?:me|up)\b|wanna\s+(?:come|go|grab|hang|get|meet|join)|want\s+to\s+(?:come|go|grab|hang|get|meet|join)|do\s+you\s+want\s+to\s+(?:come|go|grab|hang|get|meet|join)|are\s+you\s+(?:coming|free|down)\b|you\s+(?:coming|free|down)\b[^.!?\n]{0,40}\?|let'?s\s+(?:go|grab|get|meet|hang|head)\b|(?:i'?ll|let\s+me)\s+pick\s+you\s+up|be\s+my\s+date|go\s+out\s+with\s+me|see\s+you\s+(?:there|at\s+\w+|tonight|tomorrow)|i'?m\s+inviting\s+you|you'?re\s+invited)/i.test(s);
  const hu = /(?:^|[^\p{L}])(?:gyere(?:l)?|gyertek|eljössz|átjössz|jössz\s+(?:el|velem|át|ma|holnap)|van\s+kedved|nincs\s+kedved|menjünk|találkozzunk|elviszlek|érted\s+megyek|felveszlek|meghívlak|meg\s+vagy\s+hívva|ráérsz)(?=$|[^\p{L}])/iu.test(s);
  const pastOnly = /\b(?:was|were|last\s+(?:night|week|time)|yesterday)\b|tegnap|múlt(?:\s|kor)/i.test(s) && !/\?/.test(s);
  return (en || hu) && !pastOnly;
}
function groundedExtractInviteWhen(text) {
  const m = String(text || "").match(/\b(?:tonight|tomorrow|today|this\s+(?:evening|afternoon|weekend)|at\s+\d{1,2}(?::\d{2})?|ma\s+este|holnap|ma|hétvégén|\d{1,2}:\d{2})\b/iu);
  return m ? m[0] : "";
}
function groundedExtractInviteWhere(text) {
  const m = String(text || "").match(/\b(?:at|to|in)\s+([A-ZÁÉÍÓÖŐÚÜŰ][^,.!?]{2,50})|(?:a|az)\s+([^,.!?]{3,50})(?:ba|be|ra|re|hoz|hez|höz)\b/u);
  return m ? String(m[1] || m[2] || "").trim() : "";
}

function groundedUnreadDmCount(w) {
  const state = groundedRuntime(w);
  return Object.values(state && state.dmUnread || {}).reduce((sum, value) => sum + Math.max(0, Number(value) || 0), 0);
}

function groundedPlayerPostIsInvitation(post) {
  return Boolean(post && /\b(?:anyone\s+up\s+for|who\s+wants\s+to|join\s+me|come\s+with|party|hang\s*out|meet\s+up|coffee|drinks?|dinner|valaki\s+jön|ki\s+jön|gyertek|gyere|buli|találkozz|kávé|ital|vacsora)\b/iu.test(String(post.text || post.caption || "")));
}

function groundedCommentAcceptsInvitation(text) {
  /* CLAUDE FIX 5.4: a question like "who else is coming?" is not an acceptance. */
  const s = String(text || "");
  const yes = /(?<![\p{L}])(?:yes|yeah|yep|absolutely|definitely|i'?m\s+in|count\s+me\s+in|i'?ll\s+(?:come|be\s+there)|i'?m\s+coming|see\s+you\s+there|wouldn'?t\s+miss\s+it|igen|persze|naná|megyek|jövök|ott\s+leszek|benne\s+vagyok)(?![\p{L}])/iu.test(s);
  const no = /(?<![\p{L}])(?:no|nope|not\s+(?:sure|going|coming|my\s+thing)|maybe|can'?t|pass|nem\s+(?:megyek|jövök)|talán|kihagyom|passzolom)(?![\p{L}])/iu.test(s);
  return yes && !no;
}

function groundedRegisterPlayerPostInvitation(w, post, comment) {
  if (!w || !post || !comment || !isHuman(w, post.authorId) || !groundedPlayerPostIsInvitation(post) || !groundedCommentAcceptsInvitation(comment.text)) return null;
  const fromId = String(comment.authorId || comment.id || "");
  if (!fromId || isHuman(w, fromId) || !charById(w, fromId)) return null;
  groundedRuntime(w);
  const sourceRef = "comment:" + String(comment.id || "") + "@post:" + String(post.id || "");
  const existing = (w.invitations || []).find((inv) => inv && inv.status === "pending" && inv.fromId === fromId && (inv.sourceRef === sourceRef || (inv.sourcePostId && inv.sourcePostId === post.id)));
  if (existing) return existing;
  const inv = { id: "inv_" + uid(), fromId, toId: post.authorId, participantIds: [post.authorId, fromId], createdAt: now(), when: groundedExtractInviteWhen(post.text || ""), where: groundedExtractInviteWhere(post.text || ""), context: ("Post invitation: " + String(post.text || "") + " | " + nameOfIn(w, fromId) + ": " + String(comment.text || "")).slice(0, 1000), sourceRef, sourcePostId: post.id, sourceCommentId: comment.id || "", status: "pending" };
  w.invitations.unshift(inv);
  groundedEventLog(w, "invitation", "success", nameOfIn(w, fromId) + " accepted the player post invitation; scene offer created.", sourceRef, { postId: post.id, commentId: comment.id || "", participantIds: inv.participantIds });
  return inv;
}

function GroundedInvitationsPanel({ w, update, onOpenScene }) {
  const { tt } = useLang();
  const pending = (w.invitations || []).filter((inv) => inv && inv.status === "pending");
  if (!pending.length) return null;
  const decide = (invite, accept) => {
    let createdSceneId = "";
    update((n) => {
      const live = (n.invitations || []).find((row) => row && row.id === invite.id);
      if (!live || live.status !== "pending") return;
      live.status = accept ? "accepted" : "declined";
      live.resolvedAt = now();
      if (accept) {
        const from = charById(n, live.fromId);
        const scene = { id: "scene_" + uid(), title: (from ? from.name + " — " : "") + (live.where || (worldLanguage(n, n.meId) === "en" ? "Invitation" : "Meghívás")), setting: live.where || live.context || "Invitation meetup", goal: live.context || "Continue the accepted invitation naturally.", cast: (Array.isArray(live.participantIds) ? live.participantIds : [live.fromId]).filter((id) => id && !isHuman(n, id)), turns: [], open: true, createdAt: now(), ts: now(), language: worldLanguage(n, n.meId), invitationId: live.id, invitationContext: live.context, invitationParticipants: Array.isArray(live.participantIds) ? live.participantIds.slice() : [n.meId, live.fromId].filter(Boolean) };
        n.scenes = Array.isArray(n.scenes) ? n.scenes : [];
        n.scenes.unshift(scene);
        createdSceneId = scene.id;
      }
      groundedEventLog(n, "invitation", accept ? "accepted" : "declined", (accept ? "Accepted" : "Declined") + " invitation from " + nameOfIn(n, live.fromId) + ".", live.sourceRef || ("invitation:" + live.id));
    });
    if (accept && createdSceneId && typeof onOpenScene === "function") onOpenScene(createdSceneId);
  };
  return (
    <div className="card" style={{ marginTop: 0 }}>
      <div className="between"><div><div className="name">{tt("Meghívások", "Invitations")}</div><div className="hint">{pending.length} {tt("függő meghívás", "pending invitation(s)")}</div></div><span className="mono" style={{ color: "var(--rose)" }}>{pending.length}</span></div>
      {pending.map((inv) => (
        <div key={inv.id} style={{ marginTop: 12, paddingTop: 10, borderTop: "1px solid var(--line)" }}>
          <div className="name">{nameOfIn(w, inv.fromId)}</div>
          <div className="hint">{tt("Hova: ", "Where: ") + (inv.where || tt("a meghívásban megadott hely", "as in the invitation"))}{" · "}{tt("Mikor: ", "When: ") + (inv.when || tt("nincs pontosítva", "not specified"))}</div>
          <div className="body" style={{ fontSize: 13 }}>{inv.context}</div>
          <div className="row" style={{ marginTop: 9 }}><button className="btn tiny primary" onClick={() => decide(inv, true)}>{tt("Elfogadom", "Accept")}</button><button className="btn tiny" onClick={() => decide(inv, false)}>{tt("Elutasítom", "Decline")}</button></div>
        </div>
      ))}
    </div>
  );
}

function dmAutoStartScenes(w, playerId) {
  const settings = w && w.userSettings && playerId ? w.userSettings[playerId] : null;
  return Boolean(settings && settings.autoStartDmScenes === true);
}

function DmSceneAutoStartToggle({ w, update }) {
  const { tt } = useLang();
  const me = w && w.meId;
  const on = dmAutoStartScenes(w, me);
  if (!me) return null;
  return (
    <label className="hint" style={{ display: "flex", alignItems: "center", gap: 8, margin: "0 0 10px", cursor: "pointer" }}>
      <input type="checkbox" checked={on} onChange={(e) => {
        const next = e.target.checked;
        update((n) => {
          if (!n.userSettings) n.userSettings = {};
          n.userSettings[me] = { ...(n.userSettings[me] || {}), autoStartDmScenes: next };
        });
      }} />
      {tt("Ha egy DM-ben megbeszéltek egy találkozót, a jelenet magától induljon el", "When a DM agrees on meeting up, start the scene automatically")}
    </label>
  );
}

function Chat(props) {
  const { w, update, openId } = props;
  useEffect(() => {
    if (!openId) return;
    update((n) => { const state = groundedRuntime(n); if (state.dmUnread[openId]) state.dmUnread[openId] = 0; });
  }, [openId]);
  return (<>{!openId ? <DmSceneAutoStartToggle w={w} update={update} /> : null}{!openId ? <GroundedInvitationsPanel w={w} update={update} onOpenScene={props.onOpenScene} /> : null}<LegacyGroundedChat {...props} /></>);
}

function GroundedEventLogPanel({ w, update }) {
  const { tt } = useLang();
  const rows = (w.eventLog || []).slice(0, 60);
  const rereadRelationships = async () => {
    if (bondAnalysisBusy.has(w.code)) return;
    bondAnalysisBusy.add(w.code);
    try {
      const result = await rebuildBondGraph(w, { subjects: allSubjects, api: apiJson, language: worldLanguage(w), force: true });
      update(n => installBondGraph(n, result, allSubjects));
    } catch (error) { update(n => groundedEventLog(n, "relationship-reading", "failed", error.message, "manual")); }
    finally { bondAnalysisBusy.delete(w.code); }
  };
  return (
    <div className="card" style={{ marginTop: 0 }}>
      <div className="between"><div><div className="name">{tt("Eseménynapló", "Event log")}</div><div className="hint">{tt("Trigger → reakció → eredmény, konkrét forrással", "Trigger → reaction → result, with the concrete source")}</div></div><span className="mono">{rows.length}</span></div>
      <div className="row" style={{ marginTop: 8 }}><button className="btn tiny" onClick={rereadRelationships}>{tt("Kapcsolatok újraolvasása a karakterlapokból", "Re-read relationships from the character sheets")}</button></div>
      {!rows.length ? <p className="hint">{tt("Még nincs naplózott esemény.", "No logged events yet.")}</p> : null}
      {rows.map((row) => (<div key={row.id} style={{ marginTop: 10, paddingTop: 9, borderTop: "1px solid var(--line)" }}><div className="between"><span className="mono" style={{ fontSize: 10 }}>{row.kind}</span><span className="hint">{row.status}</span></div><div style={{ marginTop: 3, fontSize: 12.5 }}>{row.message}</div>{row.sourceRef ? <div className="hint mono" style={{ marginTop: 3 }}>{tt("forrás", "source")}: {row.sourceRef}</div> : null}</div>))}
    </div>
  );
}

function World(props) {
  useEffect(() => {
    const analyze = () => {
      if (!props.w?.meId || analysisReady(props.w, allSubjects) || bondAnalysisBusy.has(props.w.code) || now() < (bondAnalysisRetry.get(props.w.code) || 0)) return;
      runRelationshipReadingAction(props.w, props.update).catch(error => props.setErr(error.message));
    };
    analyze();
    const retry = setInterval(analyze, 60000);
    return () => clearInterval(retry);
  }, [props.w, props.update, props.setErr]);
  /* The event log is a background/debug tool: it is recorded and printed to the
     console, but the panel only shows with ?debug in the address. */
  const showEventLog = typeof window !== "undefined" && /[?&#]debug\b/i.test(String(window.location.search || "") + String(window.location.hash || ""));
  return (<>{showEventLog ? <GroundedEventLogPanel w={props.w} update={props.update} /> : null}<LegacyGroundedWorld {...props} /></>);
}


/* MÁSVILÁG GROUNDED EVENTS FINAL GUARDS v1 */
function groundedBondFamily(label) {
  const s = String(label || "").toLowerCase();
  if (/mother|father|mom|dad|parent|sibling|brother|sister|cousin|aunt|uncle|family|anya|apa|szülő|testvér|unokatestvér|nagynéni|nagybácsi|rokon/.test(s)) return "family";
  if (/enemy|ellens/.test(s)) return "enemy";
  if (/rival|rivális/.test(s)) return "rival";
  if (/best friend|legjobb barát/.test(s)) return "best";
  if (/close friend|közeli barát/.test(s)) return "close";
  if (/friend|barát/.test(s)) return "friend";
  if (/acquaint|ismerős/.test(s)) return "acquaintance";
  if (/stranger|idegen/.test(s)) return "stranger";
  return "";
}

function groundedBondRank(label) {
  const family = groundedBondFamily(label);
  const map = { enemy: -2, rival: -1, stranger: 0, acquaintance: 1, friend: 2, close: 3, best: 4 };
  return Object.prototype.hasOwnProperty.call(map, family) ? map[family] : null;
}

function groundedRemoveRequestedBond(row) {
  const out = { ...row };
  delete out.bond;
  delete out.type;
  return out;
}

function groundedGuardBondChange(w, row, channel, ctx = {}) {
  if (!row || typeof row !== "object") return row;
  const a = findChar(w, row.a);
  const b = findChar(w, row.b);
  if (!a || !b || a === b) return row;
  const current = getRel(w, a, b) || EMPTY_REL;
  if (current.fixed || groundedBondFamily(current.bond || current.type) === "family") {
    return groundedRemoveRequestedBond(row);
  }

  const requested = row.bond || row.type;
  if (!requested) return row;
  const oldLabel = current.bond || current.type || "";
  const oldRank = groundedBondRank(oldLabel);
  const newRank = groundedBondRank(requested);

  if (oldRank !== null && newRank !== null && Math.abs(newRank - oldRank) > 1) {
    console.info("[relationship-status-guard]", "blocked=multi-level-jump", "from=" + a, "toward=" + b, "old=" + oldLabel, "requested=" + requested, "channel=" + String(channel || ""));
    return groundedRemoveRequestedBond(row);
  }

  if (groundedBondFamily(oldLabel) === "rival" && groundedBondFamily(requested) === "enemy") {
    const why = String(row.why || ctx.reason || "");
    const strongRoleplay = channel === "roleplay" && (Math.abs(Number(row.delta) || 0) >= 6 || /betray|árul|attack|megtámad|violence|erőszak|serious threat|komoly fenyeget|humiliat|megaláz/i.test(why));
    if (!strongRoleplay) {
      console.info("[relationship-status-guard]", "blocked=rival-to-enemy-without-strong-grounded-roleplay", "from=" + a, "toward=" + b, "channel=" + String(channel || ""));
      return groundedRemoveRequestedBond(row);
    }
  }
  return row;
}

function applyChannelRelationshipChanges(w, changes, channel, ctx = {}) {
  const guarded = (Array.isArray(changes) ? changes : []).map((row) => groundedGuardBondChange(w, row, channel, ctx));
  return legacyGroundedFinalApplyChannelRelationshipChanges(w, guarded, channel, ctx);
}


